// ---------------------------------------------------------------------------
// Shared shell for every authenticated dashboard-style page: top bar,
// sidebar, i18n, language/style settings dropdown, and logout. Page-specific
// content lives in each page's own <script>, which calls
// Dashboard.initDashboard({ activePage }) once the DOM is ready.
//
// SECURITY NOTE: authGuard() below is a client-side UX guard only — it stops
// a signed-out user from briefly seeing a stale page, but it is NOT real
// access control. Every API call this page makes is authenticated again by
// the backend (session cookie), and admin-only routes are enforced there too
// (see requireAdmin in server.js) — the redirects here are just UX.
// ---------------------------------------------------------------------------

// --- CSRF token on every mutating fetch (security review, 2026-09-28,
// finding #04) -------------------------------------------------------------
// Patches window.fetch ONCE, here, before any page-specific script (loaded
// after this one in every page's <script> order) makes its first call --
// every existing `fetch(...)` call site across the whole desktop app keeps
// working unchanged, this just adds the header underneath it. Only touches
// same-origin POST/PUT/PATCH/DELETE calls -- GETs don't need it, and a
// third-party PUT (e.g. an evidence upload straight to R2's presigned URL)
// must NOT get an extra header it doesn't expect, or its own CORS policy
// rejects the preflight. See requireCsrf/issueCsrfCookie in server.js for
// why the token comes from localStorage (set at login, see login.js) rather
// than read back from the cookie -- on the desktop site that distinction
// doesn't matter (it's same-origin either way), but the exact same patch is
// mirrored in AppConfig.js for the mobile/PWA side, where it does.
(function installCsrfFetchPatch() {
    const MUTATING = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
    const originalFetch = window.fetch.bind(window);
    function getToken() {
        try { return localStorage.getItem('sgn_csrf_token'); } catch { return null; }
    }
    function setToken(token) {
        try { localStorage.setItem('sgn_csrf_token', token); } catch { /* ignore */ }
    }
    function isSameOrigin(url) {
        try { return new URL(url, window.location.href).origin === window.location.origin; } catch { return false; }
    }
    window.fetch = async function (input, init = {}) {
        const method = (init?.method || (input instanceof Request ? input.method : 'GET') || 'GET').toUpperCase();
        const url = input instanceof Request ? input.url : input;
        if (!MUTATING.has(method) || !isSameOrigin(url)) return originalFetch(input, init);

        const attempt = (token) => originalFetch(input, { ...init, headers: { ...(init.headers || {}), 'X-CSRF-Token': token || '' } });
        let res = await attempt(getToken());
        if (res.status === 403 && !getToken()) {
            // Rollout gap: a session that was already open before this
            // feature shipped never got a token at login -- mint one now
            // (the session cookie alone is enough to authorize this) and
            // retry once, so nobody has to log out/in for this to start
            // working.
            try {
                const tokenRes = await originalFetch('/api/auth/csrf-token', { credentials: 'include' });
                if (tokenRes.ok) {
                    const { csrfToken } = await tokenRes.json();
                    if (csrfToken) { setToken(csrfToken); res = await attempt(csrfToken); }
                }
            } catch { /* leave the original 403 response as-is */ }
        }
        return res;
    };
})();

// --- Mensaje de sesión terminada en el idioma de la interfaz -------------------------------------------------------------------
// La sesión dura 8 horas: al vencerse, el navegador borra la cookie y el servidor contesta 401 "Not authenticated." (o "Invalid or expired session."). Casi todas las pantallas muestran el
// mensaje del servidor tal cual, así que salía en inglés aunque la interfaz estuviera en español. Aquí se cambia, para esos dos mensajes, por el texto de main.sessionExpired (mismo
// status 401, y se agrega code: 'SESSION_EXPIRED'); las demás respuestas pasan intactas.
(function installSessionMessagePatch() {
    const SESSION_MESSAGES = new Set(['Not authenticated.', 'Invalid or expired session.']);
    const previous = window.fetch.bind(window);
    window.fetch = async function (...args) {
        const res = await previous(...args);
        if (res.status !== 401) return res;
        const body = await res.clone().json().catch(() => null);
        if (!body || !SESSION_MESSAGES.has(body.message)) return res;
        return new Response(JSON.stringify({ ...body, code: body.code || 'SESSION_EXPIRED', message: t('main.sessionExpired') }), { status: 401, statusText: res.statusText, headers: { 'Content-Type': 'application/json' } });
    };
})();

// --- Toast notifications (Éxito/Error/Info/Advertencia) --------------------
// Dashboard.showToast(message, type, { title, duration }) -- a lightweight
// replacement for the ad-hoc alert()/inline-error-text patterns scattered
// across every page's own JS. Stacks in a fixed corner, auto-dismisses
// (duration: 0 to keep it until closed by hand), never blocks the page the
// way alert() does. Exported on window.Dashboard at the bottom of this file.
const TOAST_ICONS = { success: 'bx-check-circle', error: 'bx-x-circle', info: 'bx-info-circle', warning: 'bx-error' };
const TOAST_TITLE_KEYS = {
    success: 'main.toastSuccessTitle', error: 'main.toastErrorTitle',
    info: 'main.toastInfoTitle', warning: 'main.toastWarningTitle',
};
const TOAST_DEFAULT_DURATION = 3000;

function ensureToastContainer() {
    let container = document.getElementById('toast-container');
    if (!container) {
        container = document.createElement('div');
        container.id = 'toast-container';
        container.className = 'toast-container';
        container.setAttribute('aria-live', 'polite');
        document.body.appendChild(container);
    }
    return container;
}

// El aviso con el motivo cuando el servidor rechaza un permiso por salirse de un límite (hoy: departamento no contratado); null si la
// respuesta no es un rechazo de límite, y entonces quien llama usa su aviso de siempre.
function limitErrorMessage(body) {
    if (!body || body.code !== 'module-not-contracted') return null;
    return t('admin.limitModuleNotContracted', { department: body.labelKey ? t(body.labelKey) : body.sectionId });
}

// Los límites al DAR permisos, con las mismas reglas que el servidor aplica al guardar (clampNewGrantsToLimits en db.js), para que los editores
// de Perfil y Usuario muestren con candado lo que no se puede dar en vez de dejarte marcarlo y quitarlo después:
//   'status'   : el nodo está en un Estatus que quien da el permiso (la cuenta que edita) no ve.
//   'contract' : una pantalla o columna fuera del plan y los adicionales de la empresa (General, centros de costo y los permisos gruesos no
//                cuentan; sin plan no se evalúa). El sufijo #app y el nivel de una columna se comparan contra la pantalla / el solo-ver.
// Si cambias algo aquí, cámbialo también en el servidor: hay una prueba que compara los dos.
const GRANT_COLUMN_LEVEL_SUFFIX = /\/(solo-ver|ver-y-operar|editar|autorizar|eliminar|notificar-llenado|notificar-cambio|notificar|buscar-filtrar|buscar-reordenar|buscar-ordenar)$/;
// El Notificar de un ÍCONO (<pantalla>/<ícono>/notificar) se compara contra el propio ícono, no contra un solo-ver.
const GRANT_ICON_NOTIFY_SUFFIX = /\/icon[A-Za-z]+\/notificar$/;
// mainContractGrants (2026-11-19, «limita también lo que puede dar»): lo de General (main) que el contrato del cliente trae, tal como lo manda el servidor (mainContractGrants). El administrador solo puede dar de General lo que ahí está;
// vacío o sin lista = el contrato no trae nada de General y no hay límite. Los centros de costos no cuentan. Un botón con renglones (Configuración) se puede abrir si el contrato trae algo de él; sus renglones se miden uno por uno.
function buildGrantLimits(contractGrants, mainContractGrants) {
    const contract = Array.isArray(contractGrants) ? contractGrants : null;
    const main = Array.isArray(mainContractGrants) && mainContractGrants.length ? mainContractGrants : null;
    const keyOf = (s, i, sub) => `${s}::${i || ''}::${sub || ''}`;
    const rawSet = contract ? new Set(contract.map((g) => keyOf(g.sectionId, g.itemId, g.submenuId))) : null;
    const covered = (s, i, sub) => rawSet.has(keyOf(s, i, sub)) || (!!i && rawSet.has(keyOf(s, i, null))) || rawSet.has(keyOf(s, null, null));
    const mainCovered = (itemId, submenuId) => main.some((c) => !c.itemId || (c.itemId === itemId && (!submenuId || !c.submenuId || c.submenuId === submenuId || String(submenuId).startsWith(`${c.submenuId}/`) || String(c.submenuId).startsWith(`${submenuId}/`))));
    return {
        reason(sectionId, itemId, submenuId) {
            if (!isEstatusVisible(sectionId, itemId, submenuId)) return 'status';
            if (main && sectionId === 'main' && itemId !== 'cc-list' && !String(submenuId || '').startsWith('cc-')) return mainCovered(itemId, submenuId) ? null : 'contract';
            if (!rawSet || sectionId === 'main' || !submenuId) return null;
            if (itemId === 'cc-list' || String(submenuId).startsWith('cc-')) return null;
            const base = String(submenuId).replace(/#app$/, '');
            const contractKey = GRANT_ICON_NOTIFY_SUFFIX.test(base) ? base.replace(/\/notificar$/, '') : (GRANT_COLUMN_LEVEL_SUFFIX.test(base) ? base.replace(GRANT_COLUMN_LEVEL_SUFFIX, '/solo-ver') : base);
            return covered(sectionId, itemId, contractKey) ? null : 'contract';
        },
    };
}

// El aviso cuando el servidor guardó pero quitó permisos nuevos que no caben (fuera del contrato o en un Estatus que quien da el permiso no ve);
// null si no se quitó nada.
function limitDroppedMessage(dropped) {
    if (!dropped || !dropped.count) return null;
    // Los centros de costos fuera de la asignación llevan su propio aviso; el resto, el de siempre (contrato o Estatus).
    const assignment = Number(dropped.assignment) || 0;
    if (assignment && assignment >= dropped.count) return t('admin.limitDroppedAssignment', { count: assignment });
    if (assignment) return `${t('admin.limitDroppedNotice', { count: dropped.count - assignment })} ${t('admin.limitDroppedAssignment', { count: assignment })}`;
    return t('admin.limitDroppedNotice', { count: dropped.count });
}

// Un aviso de error o de alerta que trae el texto de una ayuda de «Errores y ayuda» (TI › Catálogos) se explica solo: «¿Qué pasó?» abre qué pasó, qué se requiere, el manual y «me sirvió» / «pedir ayuda». La lista se pide una sola vez por página.
let supportHelpPromise = null;
function loadSupportHelp() {
    if (!supportHelpPromise) {
        supportHelpPromise = (typeof currentRole !== 'undefined' && currentRole === 'admin') ? Promise.resolve([])
            : fetch('/api/business/support-help', { credentials: 'include' }).then((r) => (r.ok ? r.json() : { articles: [] })).then((j) => j.articles || []).catch(() => []);
    }
    return supportHelpPromise;
}
function attachSupportExplain(msgEl, message) {
    loadSupportHelp().then((list) => {
        const m = String(message || '').toLowerCase();
        const hit = list.find((a) => a.errorText && m.includes(String(a.errorText).toLowerCase()));
        if (!hit) return;
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'toast-explain';
        btn.textContent = t('main.hlWhatHappened');
        btn.addEventListener('click', () => openSupportExplain(hit, message));
        msgEl.append(' ', btn);
    });
}
function openSupportExplain(article, message) {
    const e = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    let overlay = document.getElementById('support-explain-modal');
    if (!overlay) { overlay = document.createElement('div'); overlay.id = 'support-explain-modal'; overlay.className = 'modal-overlay'; overlay.hidden = true; document.body.appendChild(overlay); }
    const external = /^https?:/i.test(article.manualUrl || '');
    overlay.innerHTML = `<div class="modal-panel support-explain-panel" role="dialog" aria-modal="true"><h3>${e(article.title)}</h3>${article.what ? `<div><b>${e(t('main.soWhat'))}</b><p class="sp-pre">${e(article.what)}</p></div>` : ''}${article.need ? `<div><b>${e(t('main.soNeed'))}</b><p class="sp-pre">${e(article.need)}</p></div>` : ''}${article.manualUrl ? `<p><a class="btn btn-secondary" href="${e(article.manualUrl)}"${external ? ' target="_blank" rel="noopener"' : ''}>${e(article.manualTitle || t('main.soManual'))}</a></p>` : ''}<div class="admin-form-actions"><button type="button" class="btn" data-se="yes">${e(t('main.soHelped'))}</button><button type="button" class="btn btn-secondary" data-se="no">${e(t('main.soNotHelped'))}</button><button type="button" class="btn btn-secondary" data-se="close">${e(t('main.close'))}</button></div></div>`;
    overlay.onclick = async (event) => {
        const b = event.target.closest('[data-se]');
        if (!b) { if (event.target === overlay) overlay.hidden = true; return; }
        if (b.dataset.se === 'close') { overlay.hidden = true; return; }
        const helped = b.dataset.se === 'yes';
        try { await fetch(`/api/business/support-help/${article.id}/use`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ helped, source: 'error' }) }); } catch (err) { /* sin conexión */ }
        overlay.hidden = true;
        if (helped) showToast(t('main.soThanks'), 'success');
        else if (hasNotificationTabPermission('soporte')) location.href = `Soporte.html?new=1&title=${encodeURIComponent(article.title)}&error=${encodeURIComponent(message)}`;
    };
    overlay.hidden = false;
}

function showToast(message, type = 'info', { title, duration = TOAST_DEFAULT_DURATION } = {}) {
    const kind = TOAST_ICONS[type] ? type : 'info';
    const container = ensureToastContainer();

    const toast = document.createElement('div');
    toast.className = `toast toast-${kind}`;
    toast.setAttribute('role', kind === 'error' ? 'alert' : 'status');

    const iconBadge = document.createElement('span');
    iconBadge.className = 'toast-icon-badge';
    const icon = document.createElement('i');
    icon.className = `bx ${TOAST_ICONS[kind]}`;
    icon.setAttribute('aria-hidden', 'true');
    iconBadge.appendChild(icon);

    const msgEl = document.createElement('p');
    msgEl.className = 'toast-message';
    const titleEl = document.createElement('strong');
    titleEl.className = 'toast-title';
    titleEl.textContent = `${title || t(TOAST_TITLE_KEYS[kind])}: `;
    msgEl.append(titleEl, document.createTextNode(message));
    if (kind === 'warning' || kind === 'error') attachSupportExplain(msgEl, message);

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'toast-close';
    closeBtn.setAttribute('aria-label', t('main.close'));
    closeBtn.innerHTML = '<i class="bx bx-x" aria-hidden="true"></i>';

    const progress = document.createElement('div');
    progress.className = 'toast-progress';

    let dismissTimer = null;
    const close = () => {
        if (dismissTimer) clearTimeout(dismissTimer);
        toast.classList.remove('toast-visible');
        toast.addEventListener('transitionend', () => toast.remove(), { once: true });
        // Fallback in case the transitionend listener above never fires
        // (e.g. prefers-reduced-motion skips the transition entirely).
        setTimeout(() => toast.remove(), 300);
    };
    closeBtn.addEventListener('click', close);

    toast.append(iconBadge, msgEl, closeBtn, progress);
    container.appendChild(toast);
    // Force layout before adding the visible class (and starting the
    // progress-bar shrink) so both transitions actually play instead of
    // snapping straight to their end state on the very first frame.
    void toast.offsetWidth;
    toast.classList.add('toast-visible');
    if (duration) {
        progress.style.transitionDuration = `${duration}ms`;
        progress.style.width = '0';
        dismissTimer = setTimeout(close, duration);
    } else {
        progress.style.display = 'none';
    }
    return { close };
}

// --- Confirm dialog (styled replacement for window.confirm) ----------------
// Dashboard.confirm(message) -- returns a Promise<boolean>. Same visual
// language as the toast system (colored icon badge, surface card) but a
// blocking modal with Aceptar/Cancelar, since every caller needs a boolean
// answer before continuing (a toast alone can't do that). One hidden
// overlay is reused across every call instead of building a new DOM tree
// each time.
function ensureConfirmModal() {
    let modal = document.getElementById('confirm-modal');
    if (modal) return modal;
    modal = document.createElement('div');
    modal.id = 'confirm-modal';
    modal.className = 'modal-overlay confirm-modal-overlay';
    modal.hidden = true;
    modal.innerHTML = `
        <div class="modal-panel confirm-modal-panel" role="alertdialog" aria-modal="true" aria-labelledby="confirm-modal-message">
            <span class="confirm-modal-icon-badge"><i class="bx bx-help-circle" aria-hidden="true"></i></span>
            <p class="confirm-modal-message" id="confirm-modal-message"></p>
            <div class="admin-form-actions confirm-modal-actions">
                <button type="button" class="btn btn-secondary" id="confirm-modal-cancel"></button>
                <button type="button" class="btn" id="confirm-modal-accept"></button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    return modal;
}

// Opcional (options): items = una lista debajo del mensaje; accept y cancel = el texto de cada botón; extra = el texto de un tercer botón (entre Cancelar y Aceptar) que contesta 'extra'. Sin options queda como siempre.
function confirmDialog(message, options = {}) {
    return new Promise((resolve) => {
        const modal = ensureConfirmModal();
        modal.querySelector('.confirm-modal-message').textContent = message;
        modal.querySelectorAll('.confirm-modal-list').forEach((el) => el.remove());
        if (Array.isArray(options.items) && options.items.length) {
            const list = document.createElement('ul');
            list.className = 'confirm-modal-list';
            options.items.forEach((text) => { const li = document.createElement('li'); li.textContent = text; list.appendChild(li); });
            modal.querySelector('.confirm-modal-message').after(list);
        }
        const acceptBtn = modal.querySelector('#confirm-modal-accept');
        const cancelBtn = modal.querySelector('#confirm-modal-cancel');
        acceptBtn.textContent = options.accept || t('admin.confirmAccept');
        cancelBtn.textContent = options.cancel || t('admin.cancel');
        const oldExtra = modal.querySelector('#confirm-modal-extra');
        if (oldExtra) oldExtra.remove();
        let extraBtn = null;
        if (options.extra) {
            extraBtn = document.createElement('button');
            extraBtn.type = 'button';
            extraBtn.className = 'btn btn-secondary';
            extraBtn.id = 'confirm-modal-extra';
            extraBtn.textContent = options.extra;
            cancelBtn.after(extraBtn);
        }

        const done = (result) => {
            modal.hidden = true;
            acceptBtn.removeEventListener('click', onAccept);
            cancelBtn.removeEventListener('click', onCancel);
            if (extraBtn) { extraBtn.removeEventListener('click', onExtra); extraBtn.remove(); }
            modal.removeEventListener('click', onBackdrop);
            document.removeEventListener('keydown', onKeydown);
            resolve(result);
        };
        const onAccept = () => done(true);
        const onCancel = () => done(false);
        const onExtra = () => done('extra');
        const onBackdrop = (event) => { if (event.target === modal) done(false); };
        const onKeydown = (event) => { if (event.key === 'Escape') done(false); };

        acceptBtn.addEventListener('click', onAccept);
        cancelBtn.addEventListener('click', onCancel);
        if (extraBtn) extraBtn.addEventListener('click', onExtra);
        modal.addEventListener('click', onBackdrop);
        document.addEventListener('keydown', onKeydown);

        modal.hidden = false;
        acceptBtn.focus();
    });
}

