// --- Auth guard -------------------------------------------------------------
// Returns the user's role ('admin' | 'user') on success, or null (after
// redirecting to Login.html) if the session is missing/expired.
async function authGuard() {
    let res;
    try {
        res = await fetch(`${API_BASE}/me`, { credentials: 'include' });
    } catch {
        // Sin red: no se sabe si la sesión sigue o no; initDashboard muestra la alerta de "no pudimos verificar tus accesos".
        throw new Error('network');
    }
    if (res.status >= 500) throw new Error('server');
    try {
        if (!res.ok) throw new Error('not authenticated');
        const data = await res.json();
        currentUser = data.user || null;
        return data.user?.role || 'user';
    } catch {
        window.location.replace('Login.html');
        return null;
    }
}

// --- i18n --------------------------------------------------------------------
function getStoredLang() {
    const stored = localStorage.getItem('lang');
    return SUPPORTED_LANGS.includes(stored) ? stored : DEFAULT_LANG;
}

function t(key, params = {}) {
    const value = key.split('.').reduce((obj, part) => obj?.[part], dict);
    if (typeof value !== 'string') return key;
    return value.replace(/\{(\w+)\}/g, (_, name) => params[name] ?? `{${name}}`);
}

// El JSON de cada idioma se pide una sola vez (initDashboard lo pide al arrancar, a la vez que el resto, y loadLanguage lo aplica cuando llega).
const languageJsonPromises = {};
function fetchLanguageJson(lang) {
    if (!languageJsonPromises[lang]) {
        languageJsonPromises[lang] = (async () => {
            try {
                const res = await fetch(`i18n/${lang}.json`);
                if (res.ok) return await res.json();
            } catch {
                // fetch blocked (e.g. file:// protocol) — fall through to embedded copy
            }
            return null;
        })();
    }
    return languageJsonPromises[lang];
}

async function loadLanguage(lang) {
    const loaded = await fetchLanguageJson(lang);
    dict = loaded || EMBEDDED_TRANSLATIONS[lang] || EMBEDDED_TRANSLATIONS[DEFAULT_LANG];
    currentLang = lang;
    document.documentElement.lang = lang;
    localStorage.setItem('lang', lang);
    applyStaticTranslations();
    applyClientBranding(clientBranding); // re-assert: applyStaticTranslations just reset .brand span to the generic "SGN" label
    updateDatabaseMenuLabel(clientBranding); // re-assert: applyStaticTranslations just reset the database label too
    document.querySelectorAll('.lang-option').forEach((btn) => {
        btn.classList.toggle('active', btn.dataset.lang === lang);
    });
    renderFilteredMenu();
    updateDeptPickerLabel();
    renderAreaPickerOptions(); // rebuilds labels for the current department's areas
    renderCostCenterPicker(); // no-op until costCenters loads; re-translates the "Todos"/count label after that
    renderSitePicker(); // lo mismo para los sitios
    renderUserProfile(); // no-op until the profile panel has been opened at least once
    renderBusinessProfile(); // same, for the business-profile panel
    document.dispatchEvent(new CustomEvent('dashboard:language-changed', { detail: { lang } }));
}

// La flecha que contrae el menú lateral: su aria-label venía escrito en inglés en el HTML de cada
// pantalla; ahora dice la acción que haría (contraer o expandir) en el idioma elegido.
function syncSidebarToggleLabel() {
    document.getElementById('Sidebar')?.setAttribute('aria-label', t('sidebar.mainNav'));
    // Botones del celular: su aria-label venía fijo en inglés en el HTML de cada pantalla.
    document.getElementById('sidebars-btn')?.setAttribute('aria-label', t('sidebar.toggleMenu'));
    document.getElementById('top-bar-actions-toggle')?.setAttribute('aria-label', t('sidebar.moreActions'));
    const menuBtn = document.getElementById('menu-btn');
    if (!menuBtn) return;
    const minimized = document.getElementById('Sidebar')?.classList.contains('minimize');
    menuBtn.setAttribute('aria-label', t(minimized ? 'sidebar.expandMenu' : 'sidebar.collapseMenu'));
}

function applyStaticTranslations() {
    document.querySelectorAll('[data-i18n]').forEach((el) => {
        const text = t(el.dataset.i18n);
        // La unidad de un encabezado de tabla se escribe con su símbolo del Sistema Internacional (cm, kg, g, m²…) aunque el encabezado se vea en mayúsculas.
        const unit = el.tagName === 'TH' ? /^(.*?)\s*\((cm|mm|m|kg|g|ml|l|m²|m³|°C|%)\)$/.exec(text) : null;
        if (unit) {
            el.textContent = unit[1];
            const span = document.createElement('span');
            span.className = 'unit-si';
            span.textContent = ` (${unit[2]})`;
            el.appendChild(span);
        } else {
            el.textContent = text;
        }
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
        el.setAttribute('placeholder', t(el.dataset.i18nPlaceholder));
    });
    document.querySelectorAll('[data-i18n-aria]').forEach((el) => {
        el.setAttribute('aria-label', t(el.dataset.i18nAria));
    });
    // El icono de Ayuda lo crea un script (sin HTML estático) y su tooltip nativo (title) estaba
    // escrito en inglés: se traduce aquí, junto con su aria-label, y sigue al cambiar de idioma.
    document.querySelectorAll('#help-mode-toggle').forEach((el) => {
        el.title = t('main.helpMode');
    });
    syncSidebarToggleLabel();
    const titleEl = document.querySelector('title[data-i18n]');
    if (titleEl) document.title = t(titleEl.dataset.i18n);
}

let langSwitching = false;

// --- Dynamic sidebar menu ------------------------------------------------------
// Minimal embedded fallback (main navigation + footer + demo user) used only
// if data/menu.json can't be fetched (e.g. file:// protocol). The full menu
// with all department sections lives in data/menu.json — keep that as the
// source of truth for real edits.
const EMBEDDED_MENU_FALLBACK = {
    sections: [{
        id: 'main',
        items: [
            { id: 'home', labelKey: 'menu.home', icon: 'bx-home-alt-2', href: '#' },
            { id: 'panel', labelKey: 'menu.panel', icon: 'bx-grid-alt', href: '#' },
            { id: 'dashboard', labelKey: 'menu.dashboard', icon: 'bx-bar-chart-alt-2', href: 'Inicio-en.html' }
        ]
    }],
    footer: []
};

let menuLoadPromise = null;
function loadMenuOnce() {
    if (!menuLoadPromise) menuLoadPromise = loadMenu();
    return menuLoadPromise;
}
async function loadMenu() {
    try {
        const res = await fetch('data/menu.json');
        if (res.ok) return await res.json();
    } catch {
        // fetch blocked (e.g. file:// protocol) — fall through to embedded copy
    }
    console.warn('data/menu.json could not be loaded; using minimal embedded fallback menu.');
    return EMBEDDED_MENU_FALLBACK;
}

// Admin-only sidebar dropdown (SaaS control panel: Clientes Registrados —
// the list of existing clients, module entitlements, and Anexos, all on one
// screen — + Agregar Cliente Nuevo, a dedicated add-only form; Planes
// Registrados, GEIPSA's own plan-type catalog; and + Agregar Plan Nuevo,
// same add-only split as the client screens). Only ever added when the
// server-verified role (from /api/me) is 'admin' — the real access control
// is enforced server-side on every /api/admin/* route regardless of what the
// sidebar shows. Regular client users never see this; they manage their own
// access from "Administración del Negocio" instead. Placed right after
// "Tablero" in the main section, not as a separate section, so it doesn't
// read as part of the client-facing navigation.
// GEIPSA staff (role 'admin') aren't a client using the product — they're
// the SaaS operator. Their sidebar is deliberately minimal: search, Inicio,
// Tablero, and Administración de Clientes, nothing else. Client users (any
// non-admin, including a client's own isClientAdmin account) keep the full
// menu.json-driven sidebar untouched.
// "Pantalla habilitada" for GEIPSA's own SaaS-side screens (Equipo SaaS) —
// mirrors hasScreenGrant's client-side counterpart, but against
// cachedSaasGrants (GET /api/me/saas-grants) instead of a business
// profile's effectiveGrants. Zero grants = unrestricted (see
// saas_user_grants' own comment in db.js) — same convention as
// isUnrestrictedClientAdmin, so the very first admin/admin account (which
// starts with no rows here) isn't accidentally locked out of its own
// screens the moment this ships.
let cachedSaasGrants = null;
// El arranque no puede saber qué tiene habilitado la cuenta si alguna de las lecturas de permisos falló (red caída o error del servidor, no un "no tiene"):
// initDashboard lo detecta y muestra la alerta de "no pudimos verificar tus accesos" en lugar de la pantalla.
let shellLoadFailed = false;
// Estatus visibility gate, SaaS side -- same idea as
// resolveMasterNodeStatus/isEstatusVisible above, mirrored against
// saas_master_status's own flat "::"-nested item_id keys instead of the
// client tree's {sectionId,itemId,submenuId} triple (see
// resolveSaasNodeStatus's own comment in db.js -- no empty-segment
// ambiguity here, every segment of a SaaS key is always a real id).
let cachedSaasVisibleStatuses = null;
let cachedSaasStatusOverrides = null;
async function loadSaasGrants() {
    try {
        const res = await fetch(`${API_BASE}/me/saas-grants`, { credentials: 'include' });
        if (!res.ok) {
            if (res.status >= 500) shellLoadFailed = true;
            cachedSaasGrants = []; cachedSaasVisibleStatuses = ['habilitado']; cachedSaasStatusOverrides = [];
            return;
        }
        const data = await res.json();
        cachedSaasGrants = data.grants || [];
        cachedSaasVisibleStatuses = data.visibleStatuses || ['habilitado'];
        cachedSaasStatusOverrides = data.saasStatusOverrides || [];
    } catch {
        shellLoadFailed = true;
        cachedSaasGrants = [];
        cachedSaasVisibleStatuses = ['habilitado'];
        cachedSaasStatusOverrides = [];
    }
}
function resolveSaasNodeStatus(itemId) {
    const overrides = cachedSaasStatusOverrides || [];
    if (!overrides.length) return 'habilitado';
    const parts = String(itemId).split('::');
    for (let i = 1; i <= parts.length; i += 1) {
        const prefix = parts.slice(0, i).join('::');
        const hit = overrides.find((r) => r.itemId === prefix);
        if (hit) return hit.status;
    }
    return 'habilitado';
}
// CORRECTED, 2026-09-28, same fix as hasSaasGrant in db.js: zero grants no
// longer means unrestricted for just anyone -- only the one designated SaaS
// super-admin (currentUser.isSaasSuperAdmin, mirrors isClientAdmin on the
// client side) bypasses this. This is the client-side UX-only mirror of the
// real server-side check (hiding a menu item this account can't actually
// use), not itself the enforcement -- server.js's own hasSaasGrant is what
// actually protects each route.
// Bypass checked FIRST, not after the visibility gate -- reordered
// 2026-09-30 after locking myself out of Admin-ArbolMaestroSaaS.html
// locally: with 'saas-master-tree' (this screen's own new self-gating
// leaf, see GENERAL_ITEMS in Admin-ArbolMaestroSaaS.js) set to a status
// outside an account's cachedSaasVisibleStatuses, the OLD order failed the
// visibility check before ever reaching isSaasSuperAdmin, so even a real
// super-admin got redirected away from the one screen that could undo it.
// Production's admin_saas happens to have every status marked visible
// today, which is why this never surfaced before, but that's a data
// fact this function shouldn't have to depend on -- a super-admin bypass
// that a status/visibility combination can still defeat isn't a real
// bypass. Now isSaasSuperAdmin always wins, for every node, not just this
// new one.
function hasSaasScreenGrant(itemId, subItemId = null) {
    if (currentUser?.isSaasSuperAdmin) return true;
    const fullKey = subItemId ? `${itemId}::${subItemId}` : itemId;
    const visible = cachedSaasVisibleStatuses || ['habilitado'];
    if (!visible.includes(resolveSaasNodeStatus(fullKey))) return false;
    const grants = cachedSaasGrants || [];
    return grants.some((g) => g.itemId === itemId && (subItemId ? g.subItemId === subItemId : true));
}
// ¿El Estatus de este nodo es de los que la cuenta ve? (sin pedir un permiso con su id: para los grupos del menú, que no llevan permisos propios)
function isSaasNodeStatusVisible(itemId) {
    if (currentUser?.isSaasSuperAdmin) return true;
    return (cachedSaasVisibleStatuses || ['habilitado']).includes(resolveSaasNodeStatus(itemId));
}
// Equipo SaaS and Árbol Maestro SaaS itself used to be a deliberate
// exception here -- restricting who can see them would need to be granted
// BY someone who can already see them, a bootstrapping problem. Removed
// 2026-09-30, confirmed live: "SOLO EL USUARIO admin_saas tiene accesos a
// todo... los usuarios de prueba tienen la misma estructura" -- the
// bootstrapping risk is solved by admin_saas's own isSaasSuperAdmin bypass
// (hasSaasScreenGrant above) instead of leaving either screen permanently
// ungated for every account. 'saas-team' already had a real catalog entry
// (SaasAdminCatalog.js, under saasConfig) that nothing pointed at yet;
// 'saas-master-tree' is a new GENERAL_ITEMS leaf (Admin-ArbolMaestroSaaS.js,
// this screen describing itself). Kept as its own map (not folded into
// SCREEN_GRANT_PATHS) since
// it's a completely separate namespace (flat itemId, no
// {sectionId,itemId,submenuId} triple). Extended 2026-09-29 (was just these
// 3) to cover every real SaaS-admin screen that also carries a saasItemId
// in buildSidebarData's own item list below -- admin-nuestras-apps/admin-
// master-permissions/admin-business-
// sectors/admin-nuestros-respaldos/admin-material-apoyo were already hidden
// from the sidebar correctly when their Estatus wasn't visible, but typing
// their URL directly still worked regardless (this map only ever gated
// direct access, not the sidebar). Confirmed live: "porque si Giro está en
// mejora, se visualiza en la barra lateral?" -- admin-business-sectors
// specifically had NO saasItemId at all yet, in either place, so it never
// respected Estatus for sidebar OR direct access.
const SAAS_SCREEN_GRANT_PATHS = {
    'admin-saas': 'saas-clients',
    'admin-planes': 'saas-plans',
    'admin-nuestras-apps': 'saas-apps',
    'admin-master-permissions': 'saas-master-permissions-tree',
    'admin-business-sectors': 'saas-business-sectors',
    'admin-soporte-saas': 'saas-support',
    'admin-expansiones-saas': 'saas-expansions',
    'admin-capacitacion-saas': 'saas-training',
    'admin-implementaciones-saas': 'saas-implementations',
    'admin-apps-clientes-saas': 'saas-client-logins',
    'admin-limits-audit': 'saas-limits-audit',
    'admin-system-reset': 'saas-system-reset',
    'admin-access-relations': 'saas-access-relations',
    'admin-equipo-saas': 'saas-team',
    'admin-saas-master-status': 'saas-master-tree',
    'admin-nuestros-respaldos': 'saas-backups',
    'admin-material-apoyo': 'saas-material-apoyo',
};
function hasSaasScreenAccess(activePage) {
    const itemId = SAAS_SCREEN_GRANT_PATHS[activePage];
    if (!itemId) return true;
    return hasSaasScreenGrant(itemId);
}

// Per-table Iconos Personalización, SaaS side -- mirrors hasIconGrant's own
// client-side check, but against the SaaS tree's Estatus instead of a
// profile grant (there's no per-account icon-level grant yet -- see
// SaasAdminCatalog.js's own comment on "el árbol de permisos POR CUENTA...
// todavía no profundiza"). Confirmed live, 2026-09-28: "todas las tablas
// deben llevar su clasificación... la cual se define desde el árbol de
// permisos" -- Árbol Maestro SaaS already gives every Iconos Personalización
// leaf its own Estatus selector (see ICON_PERSONALIZATION_ITEMS/buildLeaves
// in Admin-ArbolMaestroSaaS.js), this is what actually makes that selector
// do something at runtime; before this it was purely cosmetic. Returns null
// (not a SaaS table) so callers fall back to hasIconGrant for every other
// table -- resolveIconGrant below is that fallback dispatcher.
// Every SaaS-admin screen whose table is modeled in the SaaS tree (a
// tablaApartado in SaasAdminCatalog.js carries the Iconos Personalización
// leaves) -- extended 2026-10-02 from the first 3 to all 7, so the same
// icons (Acomodo Guardado included) work, and obey the tree, on every SaaS
// table, not just some.
const SAAS_TABLE_ICON_SCREENS = {
    'equipo-saas': { screenItemId: 'saas-team', apartadoId: 'tabla' },
    'nuestros-clientes': { screenItemId: 'saas-clients', apartadoId: 'tabla' },
    'mis-planes': { screenItemId: 'saas-plans', apartadoId: 'tabla' },
    'nuestras-apps': { screenItemId: 'saas-apps', apartadoId: 'catalogo' },
    'business-sectors': { screenItemId: 'saas-business-sectors', apartadoId: 'tabla' },
    'soporte-saas': { screenItemId: 'saas-support', apartadoId: 'tabla' },
    'expansiones-saas': { screenItemId: 'saas-expansions', apartadoId: 'tabla' },
    'capacitacion-saas': { screenItemId: 'saas-training', apartadoId: 'tabla' },
    'implementaciones-saas': { screenItemId: 'saas-implementations', apartadoId: 'tabla' },
    'apps-clientes-saas': { screenItemId: 'saas-client-logins', apartadoId: 'tabla' },
    'admin-nuestros-respaldos': { screenItemId: 'saas-backups', apartadoId: 'tabla' },
    'admin-material-apoyo': { screenItemId: 'saas-material-apoyo', apartadoId: 'tabla' },
};
// Tablas que guardan sus búsquedas y acomodos del lado de SaaS (rutas
// /api/admin/saas-saved-*, sin cliente): las siete de arriba y, para una cuenta
// de SaaS (sin clientId), cualquier otra tabla que vea -- Base de Datos, etc.
// Esas rutas aceptan cualquier tableKey; antes solo estas siete tenían los iconos
// de Búsqueda y Acomodo Guardado, y en las demás faltaban aunque se tuviera todo.
function isSaasTableKey(tableId) {
    if (SAAS_TABLE_ICON_SCREENS[tableId]) return true;
    return !!currentUser && !currentUser.clientId;
}

function hasSaasTableIconGrant(tableId, iconId) {
    const mapping = SAAS_TABLE_ICON_SCREENS[tableId];
    if (!mapping) return null;
    const key = `${mapping.screenItemId}::${mapping.apartadoId}::icon-${iconId}`;
    const visible = cachedSaasVisibleStatuses || ['habilitado'];
    return visible.includes(resolveSaasNodeStatus(key));
}

// Árbol Maestro SaaS's own reorder (saas_master_order, edited on
// Admin-ArbolMaestroSaaS.html) used to only ever change that screen's own
// tree display -- confirmed live that dragging "Giros de Negocio" above
// "Árbol de Permisos Maestro" there and saving left the REAL sidebar below
// untouched, exactly the "solo cambia el árbol, no la pantalla real" gap
// the user has been explicit this whole effort must never happen. Fetched
// once per session load, same pattern as loadSaasGrants above.
let cachedSaasMasterOrder = null;
async function loadSaasMasterOrder() {
    try {
        const res = await fetch(`${API_BASE}/admin/saas-master-order`, { credentials: 'include' });
        if (!res.ok) { cachedSaasMasterOrder = null; return; }
        const data = await res.json();
        cachedSaasMasterOrder = data.order || null;
    } catch {
        cachedSaasMasterOrder = null;
    }
}
// Maps a sidebar item's own `id` to the itemId SaasAdminCatalog.js (and so
// saas_master_order.screensByGroup) actually uses -- the two namespaces
// never lined up 1:1 (this sidebar predates that catalog). Every
// sidebar screen has an entry, Admin-ArbolMaestroSaaS.html included
// (saas-master-tree, a catalog screen of Configuración SaaS since
// 2026-09-30): the Árbol Maestro SaaS is the one that sets the real order,
// so the sidebar, the tree itself and each account's access dialog
// (Admin-EquipoSaaS.js) must all list screens in that same order -- a
// screen pinned at a fixed slot here made the sidebar disagree with it.
const CUSTOMER_SERVICE_SAAS_ORDER_IDS = {
    'admin-clientes-registrados': 'saas-clients',
    'admin-planes-registrados': 'saas-plans',
    'admin-nuestras-apps': 'saas-apps',
    'admin-master-permissions': 'saas-master-permissions-tree',
    'admin-business-sectors': 'saas-business-sectors',
    'admin-soporte-saas': 'saas-support',
    'admin-expansiones-saas': 'saas-expansions',
    'admin-capacitacion-saas': 'saas-training',
    'admin-implementaciones-saas': 'saas-implementations',
    'admin-apps-clientes-saas': 'saas-client-logins',
};
const SAAS_CONFIG_SAAS_ORDER_IDS = {
    'admin-saas-master-status': 'saas-master-tree',
    'admin-equipo-saas': 'saas-team',
    'admin-nuestros-respaldos': 'saas-backups',
    'admin-material-apoyo': 'saas-material-apoyo',
    'admin-limits-audit': 'saas-limits-audit',
    'admin-system-reset': 'saas-system-reset',
    'admin-access-relations': 'saas-access-relations',
};
// Same "most specific wins, else keep original relative position" idea
// PermissionTree.js's own applyOrder uses -- anything saas_master_order
// doesn't mention (a pinned item with no catalog id, or a screen added
// after the order was last saved) is never dropped, just left where it
// already was.
function applySaasSidebarOrder(items, groupId, idToCatalogItemId) {
    const orderIds = cachedSaasMasterOrder?.screensByGroup?.[groupId];
    if (!orderIds || !orderIds.length) return items;
    // An item with no catalog id (Árbol Maestro SaaS's own pinned slot in
    // Configuración SaaS) never takes part in the reorder -- confirmed live
    // that treating it as merely "unmatched" (appended after everything
    // else, same as applyOrder does elsewhere) silently dragged it from
    // first to last instead of leaving it put. Split it out by its exact
    // original index, reorder only the real catalog screens around it, then
    // splice it back into that same index.
    const reorderable = [];
    const fixed = [];
    items.forEach((item, index) => {
        if (idToCatalogItemId[item.id]) reorderable.push(item);
        else fixed.push({ index, item });
    });
    const byCatalogId = new Map(reorderable.map((item) => [idToCatalogItemId[item.id], item]));
    const used = new Set();
    const ordered = [];
    orderIds.forEach((catId) => {
        const item = byCatalogId.get(catId);
        if (item && !used.has(item)) { ordered.push(item); used.add(item); }
    });
    reorderable.forEach((item) => { if (!used.has(item)) ordered.push(item); });
    fixed.forEach(({ index, item }) => ordered.splice(Math.min(index, ordered.length), 0, item));
    return ordered;
}

function buildSidebarData(data, role, activePage) {
    // Split in two (was one "Administración de Clientes" dropdown) --
    // Servicio a Cliente is working a real client account; Configuración
    // SaaS is the platform/product catalog and GEIPSA's own internal
    // operation, neither of which depends on which client you're looking
    // at. Explicit product decision (2026-09-14) even though this sidebar
    // was originally built "deliberately minimal" (one dropdown only) --
    // see this function's git history for that original reasoning.
    const customerServiceSubmenu = [
        // "+ Agregar Cliente Nuevo" y "+ Agregar Plan Nuevo" no tienen
        // entrada propia aquí — Nuestros Clientes y Nuestros Planes tienen
        // su propio botón "+ Agregar ... Nuevo" en el toolbar de su tabla
        // (ver renderNewClientButton en Admin-SaaS.js / renderNewPlanButton
        // en Admin-Planes.js), que abre el mismo modal de Editar en modo
        // creación ("pantalla alterna") — nunca existieron como páginas
        // propias en el sidebar, un ítem aquí sería redundante.
        { id: 'admin-clientes-registrados', labelKey: 'menu.clientesRegistrados', href: 'Admin-SaaS.html', icon: 'bx-group', saasItemId: 'saas-clients' },
        { id: 'admin-planes-registrados', labelKey: 'menu.plansRegistered', href: 'Admin-Planes.html', icon: 'bx-package', saasItemId: 'saas-plans' },
        { id: 'admin-nuestras-apps', labelKey: 'menu.ourApps', href: 'Admin-NuestrasApps.html', icon: 'bx-grid-alt', saasItemId: 'saas-apps' },
        // Apps Nuestros Clientes: el inicio de sesión personalizado de cada cliente (computadora y celular).
        { id: 'admin-apps-clientes-saas', labelKey: 'menu.saasClientLogins', href: 'Admin-AppsClientes.html', icon: 'bx-devices', saasItemId: 'saas-client-logins' },
        // Upstream of Nuestros Giros de Negocio -- a Giro's own default
        // access tree (sector_grants) will only be allowed to grant nodes
        // marked 'habilitado' here (deferred, not built yet), so it's
        // listed right before it. Under Servicio a Cliente (not Config.
        // SaaS) -- both this and Giro de Negocio directly shape what a
        // client account ends up able to see, same as Nuestros Clientes/
        // Planes above (corrected 2026-09-15, initially miscategorized).
        {
            id: 'admin-master-permissions', labelKey: 'menu.masterPermissionsTree', href: 'Admin-ArbolMaestro.html', icon: 'bx-sitemap', saasItemId: 'saas-master-permissions-tree',
            // Same ladder idea as admin-business-sectors below -- this label
            // used to ellipsize straight to "Árbol de Permisos Mae..." even
            // though "Árbol Permisos Mtro." fits the sidebar's own width on
            // its own.
            abbrKeys: ['menu.masterPermissionsTreeAbbr1', 'menu.masterPermissionsTreeAbbr2', 'menu.masterPermissionsTreeAbbr3', 'menu.masterPermissionsTreeAbbr4'],
        },
        {
            id: 'admin-business-sectors', labelKey: 'menu.businessSectors', href: 'Admin-BusinessSectors.html', icon: 'bx-briefcase', saasItemId: 'saas-business-sectors',
            // Longest label in this dropdown -- steps down this ladder (in
            // order) until one fits the sidebar's fixed expanded width
            // instead of ellipsizing straight to "..." (see
            // applySubmenuAbbreviations below).
            abbrKeys: ['menu.businessSectorsAbbr1', 'menu.businessSectorsAbbr2', 'menu.businessSectorsAbbr3', 'menu.businessSectorsAbbr4'],
        },
        // Soporte: el Nivel 4 (el proveedor). Los casos de los clientes que llegaron hasta GEIPSA.
        { id: 'admin-soporte-saas', labelKey: 'menu.saasSupport', href: 'Admin-SoporteCasos.html', icon: 'bx-support', saasItemId: 'saas-support' },
        // Expansiones: las solicitudes de ampliar el contrato de todos los clientes.
        { id: 'admin-expansiones-saas', labelKey: 'menu.saasExpansions', href: 'Admin-Expansiones.html', icon: 'bx-trending-up', saasItemId: 'saas-expansions' },
        // Sesiones de capacitación: el implementador registra las de todas las compañías y marca quién asistió.
        { id: 'admin-capacitacion-saas', labelKey: 'menu.saasTraining', href: 'Admin-Capacitacion.html', icon: 'bx-chalkboard', saasItemId: 'saas-training' },
        // Implementaciones: el implementador inicia la implementación de cada compañía, fija fechas por nivel y marca lo terminado.
        { id: 'admin-implementaciones-saas', labelKey: 'menu.saasImplementations', href: 'Admin-Implementaciones.html', icon: 'bx-rocket', saasItemId: 'saas-implementations' },
    ].filter((item) => !item.saasItemId || hasSaasScreenGrant(item.saasItemId));
    const customerServiceSubmenuOrdered = applySaasSidebarOrder(customerServiceSubmenu, 'customerService', CUSTOMER_SERVICE_SAAS_ORDER_IDS);
    const saasConfigSubmenu = [
        // Upstream of Equipo SaaS/Nuestros Respaldos/Material de Apoyo below
        // -- same "readiness gate before per-person grants" relationship
        // Árbol de Permisos Maestro has with Giro de Negocio, just for
        // GEIPSA's own internal screens instead of the client-facing ones.
        // Its own table (saas_master_status) -- never master_permission_status.
        {
            id: 'admin-saas-master-status', labelKey: 'menu.saasMasterTree', href: 'Admin-ArbolMaestroSaaS.html', icon: 'bx-shield', saasItemId: 'saas-master-tree',
            abbrKeys: ['menu.saasMasterTreeAbbr1', 'menu.saasMasterTreeAbbr2'],
        },
        { id: 'admin-equipo-saas', labelKey: 'menu.saasTeam', href: 'Admin-EquipoSaaS.html', icon: 'bx-id-card', saasItemId: 'saas-team' },
        { id: 'admin-nuestros-respaldos', labelKey: 'menu.ourBackups', href: 'Admin-NuestrosRespaldos.html', icon: 'bx-cloud-upload', saasItemId: 'saas-backups' },
        {
            id: 'admin-material-apoyo', labelKey: 'menu.ourSupportMaterial', href: 'Admin-MaterialApoyo.html', icon: 'bx-book-open', saasItemId: 'saas-material-apoyo',
            // Same ladder idea as the other long labels in this sidebar --
            // used to hard-ellipsize to "Nuestro Material de ..." instead of
            // stepping down to something still readable.
            abbrKeys: ['menu.ourSupportMaterialAbbr1', 'menu.ourSupportMaterialAbbr2', 'menu.ourSupportMaterialAbbr3'],
        },
        { id: 'admin-limits-audit', labelKey: 'menu.limitsAudit', href: 'Admin-AuditoriaLimites.html', icon: 'bx-shield-quarter', saasItemId: 'saas-limits-audit' },
        { id: 'admin-access-relations', labelKey: 'menu.accessRelations', href: 'Admin-RelacionAccesos.html', icon: 'bx-git-compare', saasItemId: 'saas-access-relations', abbrKeys: ['menu.accessRelationsAbbr1', 'menu.accessRelationsAbbr2'] },
        { id: 'admin-system-reset', labelKey: 'menu.systemReset', href: 'Admin-ReinicioSistema.html', icon: 'bx-reset', saasItemId: 'saas-system-reset' },
    ].filter((item) => !item.saasItemId || hasSaasScreenGrant(item.saasItemId));
    const saasConfigSubmenuOrdered = applySaasSidebarOrder(saasConfigSubmenu, 'saasConfig', SAAS_CONFIG_SAAS_ORDER_IDS);
    const customerServiceItem = {
        id: 'admin-servicio-cliente', labelKey: 'menu.customerService', icon: 'bx-support', submenu: customerServiceSubmenuOrdered,
        abbrKeys: ['menu.customerServiceAbbr1', 'menu.customerServiceAbbr2'], saasGroupId: 'customerService',
    };
    const saasConfigItem = {
        id: 'admin-config-saas', labelKey: 'menu.saasConfig', icon: 'bx-cog', submenu: saasConfigSubmenuOrdered,
        abbrKeys: ['menu.saasConfigAbbr1', 'menu.saasConfigAbbr2'], saasGroupId: 'saasConfig',
    };
    if (role !== 'admin') return data;

    const mainSection = data.sections.find((s) => s.id === 'main');
    // Inicio/Tablero themselves have real Estatus rows too (saas-home/
    // saas-board, GENERAL_ITEMS in Admin-ArbolMaestroSaaS.js) -- confirmed
    // live, 2026-09-30: "porque siguen apareciendo estas 3 opciones?...
    // todo debe de habilitarse desde el árbol", against a screenshot
    // showing Inicio/Tablero still visible for a zero-grant account. Same
    // rule as every other item now: gated, not a free pass.
    const home = hasSaasScreenGrant('saas-home') ? mainSection?.items.find((i) => i.id === 'home') : null;
    const dashboard = hasSaasScreenGrant('saas-board') ? mainSection?.items.find((i) => i.id === 'dashboard') : null;
    // The 2 category dropdowns themselves are also reorderable in Árbol
    // Maestro SaaS (order.groups) -- confirmed live this was STILL missed
    // even after fixing each group's own internal screen order: dragging
    // "Configuración SaaS" above "Servicio a Cliente" and saving left these
    // two exactly where they always were. Same applySaasSidebarOrder logic,
    // keyed by the group's own saasGroupId rather than a per-screen id.
    const groupOrderIds = cachedSaasMasterOrder?.groups;
    let orderedGroupItems = [customerServiceItem, saasConfigItem];
    if (groupOrderIds && groupOrderIds.length) {
        const byGroupId = new Map(orderedGroupItems.map((item) => [item.saasGroupId, item]));
        const used = new Set();
        const ordered = [];
        groupOrderIds.forEach((groupId) => {
            const item = byGroupId.get(groupId);
            if (item && !used.has(item)) { ordered.push(item); used.add(item); }
        });
        orderedGroupItems.forEach((item) => { if (!used.has(item)) ordered.push(item); });
        orderedGroupItems = ordered;
    }
    // The group header itself (Servicio a Cliente / Config. SaaS) has its
    // own real Estatus row in Árbol Maestro SaaS (the "Apartado" line the
    // 2 groups render as there), but nothing ever checked it -- only each
    // CHILD screen's own saasItemId was gated, so a zero-grant account with
    // every child hidden still saw the parent group itself, expandable into
    // an empty dropdown. Confirmed live, 2026-09-30, against daniel.anaya:
    // "Servicio a Cliente"/"Config. SaaS" both still showed with nothing
    // inside. hasSaasScreenGrant(saasGroupId) mirrors the per-item check
    // exactly; the submenu.length guard is a second, independent reason to
    // hide the same empty-dropdown case even if that ever diverges from the
    // group's own node.
    // El grupo NO lleva permisos propios: el árbol de accesos de la cuenta solo da permisos de pantallas (itemId de cada pantalla), nunca uno con el id del grupo.
    // Pedir hasSaasScreenGrant(grupo) lo escondía SIEMPRE para una cuenta que no es la principal, aunque tuviera pantallas asignadas (Daniel, 2026-10-07: «porque
    // si ya le asigné, no me aparece en el perfil»). Ahora el grupo se muestra si tiene al menos una pantalla visible y su Estatus es de los que la cuenta ve.
    orderedGroupItems = orderedGroupItems.filter((item) => item.submenu.length > 0 && isSaasNodeStatusVisible(item.saasGroupId));
    return { ...data, sections: [{ id: 'main', items: [home, dashboard, ...orderedGroupItems].filter(Boolean) }] };
}

// --- Department picker --------------------------------------------------------
// Matches the section ids in public/data/menu.json (and the module catalog
// used by "Contrataciones") so picking a department shows exactly that
// section's items below, instead of every department stacked at once.
const DEPARTMENTS = [
    { key: 'finance', labelKey: 'menu.finance', abbrKey: 'sidebar.deptAbbr.finance', icon: 'bx-dollar-circle' },
    { key: 'accounting', labelKey: 'menu.accounting', abbrKey: 'sidebar.deptAbbr.accounting', icon: 'bx-calculator' },
    { key: 'human-resources', labelKey: 'menu.humanResources', abbrKey: 'sidebar.deptAbbr.humanResources', icon: 'bx-id-card' },
    { key: 'marketing', labelKey: 'menu.marketing', abbrKey: 'sidebar.deptAbbr.marketing', icon: 'bx-broadcast' },
    { key: 'commercial', labelKey: 'menu.commercial', abbrKey: 'sidebar.deptAbbr.commercial', icon: 'bx-store-alt' },
    { key: 'purchasing', labelKey: 'menu.purchasing', abbrKey: 'sidebar.deptAbbr.purchasing', icon: 'bx-cart-alt' },
    { key: 'supply-chain', labelKey: 'menu.supplyChain', abbrKey: 'sidebar.deptAbbr.supplyChain', icon: 'bx-package' },
    { key: 'management-control', labelKey: 'menu.managementControl', abbrKey: 'sidebar.deptAbbr.managementControl', icon: 'bx-line-chart' },
    { key: 'general-management', labelKey: 'menu.generalManagement', abbrKey: 'sidebar.deptAbbr.generalManagement', icon: 'bx-crown' },
    { key: 'steering-committee', labelKey: 'menu.steeringCommittee', abbrKey: 'sidebar.deptAbbr.steeringCommittee', icon: 'bx-group' },
    { key: 'certifications', labelKey: 'menu.certifications', abbrKey: 'sidebar.deptAbbr.certifications', icon: 'bx-certification' },
    { key: 'information-technology', labelKey: 'menu.informationTechnology', abbrKey: 'sidebar.deptAbbr.informationTechnology', icon: 'bx-chip' },
    // Análisis: sus áreas son los departamentos del cliente (ver availableAreasForDepartment); se vende aparte (adicional).
    { key: 'analysis', labelKey: 'menu.analysis', abbrKey: 'sidebar.deptAbbr.analysis', icon: 'bx-analyse' }
];
const ALWAYS_VISIBLE_SECTIONS = ['main'];

// Narrowed to the client's contracted modules once initDashboard() loads
// them (see fetchContractedModuleKeys) — starts as the full catalog so
// nothing breaks before that fetch resolves; admin/GEIPSA never shows the
// picker at all, so it's simply never narrowed for that role.
let availableDepartments = DEPARTMENTS;
// Los departamentos que la persona tiene asignados (Mi Recurso Humano > Lo que hace) pero que su Puesto todavía no le da: el selector los muestra bloqueados, con su motivo, en vez de esconderlos.
let lockedDepartments = [];
// Raw contracted-module keys (departments + top-bar buttons), kept around
// after initDashboard() loads them so syncTopBarButtonVisibility() can
// re-check it without needing its own fetch.
let contractedModuleKeys = [];

async function fetchContractedModuleKeys() {
    try {
        const res = await fetch(`${API_BASE}/business/contracted-modules`);
        if (!res.ok) {
            if (res.status >= 500) shellLoadFailed = true;
            return [];
        }
        const data = await res.json();
        return data.moduleKeys || [];
    } catch {
        shellLoadFailed = true;
        return [];
    }
}

function getStoredDepartment() {
    const stored = localStorage.getItem('department');
    return availableDepartments.some((d) => d.key === stored) ? stored : null;
}

let selectedDepartment = getStoredDepartment();

// Only the always-visible sections + whichever department is selected.
// Sin departamento elegido (y habiendo departamentos entre los que elegir) la barra lateral de una cuenta de un cliente no muestra NINGUNA opción, ni siquiera Inicio, Panel y Tablero (ni, por lo tanto, el buscador): todo cuelga de un departamento
// y hasta que se elige uno no hay nada que mostrar. Si el cliente no tiene ningún departamento entre los que elegir se deja como estaba (si no, la cuenta se quedaría sin ninguna opción y sin cómo elegir). El personal SaaS no tiene selector de departamento.
// Lo mismo con el ÁREA (Daniel, 2026-11-18): con el departamento elegido pero sin área tampoco sale nada (ni Inicio, Panel y Tablero): esos tres aparecen cuando se elige un área, los que esa persona tenga asignados. Si el
// departamento no tiene ningún área entre las que elegir se deja como estaba.
function applyDepartmentFilter(data) {
    if (currentRole !== 'admin' && availableDepartments.length > 0
        && (!selectedDepartment || (!selectedArea && availableAreasForDepartment(selectedDepartment).length > 0))) {
        return { ...data, sections: [] };
    }
    return {
        ...data,
        sections: data.sections.filter(
            (s) => ALWAYS_VISIBLE_SECTIONS.includes(s.id) || s.id === selectedDepartment
        )
    };
}

// --- Area picker (linked to the department picker) --------------------------
// Each department has its own list of areas; picking one further narrows
// that department's menu items down to just the ones tagged with that area
// (item.area in menu.json), the same way picking a department narrows
// sections. Supply Chain has real area names; every other department reuses
// the generic "Area 1/2/3" placeholders that already back its existing
// dept-N items, until real names are provided for those too.
const GENERIC_AREAS = [
    { key: 'area-1', labelKey: 'menu.area.generic', labelParams: { n: 1 }, icon: 'bx-folder' },
    { key: 'area-2', labelKey: 'menu.area.generic', labelParams: { n: 2 }, icon: 'bx-folder' },
    { key: 'area-3', labelKey: 'menu.area.generic', labelParams: { n: 3 }, icon: 'bx-folder' }
];
const AREAS_BY_DEPARTMENT = {
    'supply-chain': [
        { key: 'sc-area-raw-material', labelKey: 'menu.area.rawMaterial', icon: 'bx-cube' },
        { key: 'sc-area-production', labelKey: 'menu.area.production', icon: 'bx-cog' },
        { key: 'sc-area-transport-1', labelKey: 'menu.area.transportVolume', icon: 'bx-car' },
        { key: 'sc-area-distribution-center', labelKey: 'menu.area.distributionCenter', icon: 'bx-building' },
        { key: 'sc-area-transport-2', labelKey: 'menu.area.transportLastMile', icon: 'bx-car' },
        { key: 'sc-area-point-of-sale', labelKey: 'menu.area.pointOfSale', icon: 'bx-store' },
        { key: 'sc-area-delivery', labelKey: 'menu.area.delivery', icon: 'bx-send' },
        { key: 'sc-area-end-customer', labelKey: 'menu.area.endCustomer', icon: 'bx-user' },
        { key: 'sc-area-customer-complaints', labelKey: 'menu.area.customerComplaints', icon: 'bx-error-circle' }
    ],
    finance: GENERIC_AREAS,
    accounting: GENERIC_AREAS,
    'human-resources': [
        { key: 'hr-area-recruitment', labelKey: 'menu.area.recruitment', icon: 'bx-user-plus' },
        { key: 'hr-area-personnel-admin', labelKey: 'menu.area.personnelAdmin', icon: 'bx-id-card' },
        { key: 'hr-area-training-development', labelKey: 'menu.area.trainingDevelopment', icon: 'bx-book-open' },
        { key: 'hr-area-compensation-benefits', labelKey: 'menu.area.compensationBenefits', icon: 'bx-money' },
        { key: 'hr-area-organizational-development', labelKey: 'menu.area.organizationalDevelopment', icon: 'bx-sitemap' },
        { key: 'hr-area-occupational-health-safety', labelKey: 'menu.area.occupationalHealthSafety', icon: 'bx-plus-medical' },
        { key: 'hr-area-hris', labelKey: 'menu.area.hris', icon: 'bx-server' },
        { key: 'hr-area-hr-analytics', labelKey: 'menu.area.hrAnalytics', icon: 'bx-line-chart' }
    ],
    marketing: GENERIC_AREAS,
    commercial: GENERIC_AREAS,
    purchasing: GENERIC_AREAS,
    'management-control': GENERIC_AREAS,
    'general-management': GENERIC_AREAS,
    'steering-committee': GENERIC_AREAS,
    certifications: [
        { key: 'cert-area-iso-9001', labelKey: 'menu.area.iso9001', abbrKey: 'menu.area.iso9001Abbr', icon: 'bx-badge-check' }
    ],
    'information-technology': [
        { key: 'it-area-operations', labelKey: 'menu.area.itOperations', icon: 'bx-chip' },
        { key: 'it-area-company-config', labelKey: 'menu.area.itCompanyConfig', icon: 'bx-cog' },
        { key: 'it-area-implementation', labelKey: 'menu.area.itImplementation', icon: 'bx-rocket' }
    ],
    // Una área por departamento (an-area-<departamento>); solo sale la de un departamento que el cliente tiene contratado y solo existen las que ya tienen análisis (hoy Cadena de Suministro).
    analysis: [
        { key: 'an-area-supply-chain', labelKey: 'menu.supplyChain', icon: 'bx-package' }
    ]
};

function getStoredArea() {
    const stored = localStorage.getItem('area');
    const areas = AREAS_BY_DEPARTMENT[selectedDepartment] || [];
    return areas.some((a) => a.key === stored) ? stored : null;
}

let selectedArea = getStoredArea();

// Sitios de la barra de arriba (entre Área y Centros de Costo). Un sitio es el «código del sitio» de un centro de costos (el mismo de Asignación a laborar). Selección de varios, igual que la de centros:
// 'all' = todos (por omisión, así nadie tiene que elegir nada para seguir trabajando) o un conjunto de códigos; se recuerda en este navegador.
const SITE_SELECTION_KEY = 'siteSelection';
function getStoredSiteSelection() {
    const raw = localStorage.getItem(SITE_SELECTION_KEY);
    if (!raw || raw === 'all') return 'all';
    try {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) return new Set(parsed.map(String));
    } catch { /* por omisión: todos */ }
    return 'all';
}
let selectedSiteCodes = getStoredSiteSelection();
let sidebarSites = []; // [{ code, sucursal }] de los centros que esta cuenta puede ver (y, para el administrador del cliente, todos sus sitios activos aunque todavía no tengan centros)
let sidebarClientSites = []; // los sitios activos del cliente (registros propios de Sitios Contratados), solo para el administrador del cliente

// Every department's section is empty in menu.json — once an area is picked
// (any area, any department), the selected department's section shows the
// same shared category template (data.areaCategories: General/Catálogos/
// Operaciones/Admin/Gestión/Reportes/Material Apoyo) instead of per-area
// content. Real screens replace today's placeholders inside that one array
// as they're built, rather than needing edits in every department section.
//
// A specific área can instead need its own real submenu for one of those
// categories (e.g. Cadena de Suministro > Transporte Volumen's own
// Operaciones items) — data.areaOverrides["dept/área"][categoryId] swaps
// that one category's submenu in, leaving every other área/categoría on
// the shared template untouched. See PermissionTree.js for the matching
// (department-wide, not área-scoped) grant side of the same data.
// Un apartado marcado hideWhenEmpty (menu.json: «Cargas Manuales») solo sale en las áreas que le tienen pantallas propias (areaOverrides); en las demás ni se dibuja.
const isHiddenEmptyCategory = (cat) => !!cat.hideWhenEmpty && !(cat.submenu && cat.submenu.length);
// Departamentos donde un apartado sin pantallas para esta persona no se dibuja (en los demás sale atenuado, regla del 2026-11-18). Análisis solo tiene sus dos apartados; los seis de siempre irían vacíos (Daniel, 2026-11-25).
const HIDE_EMPTY_CATEGORIES_IN = new Set(['analysis']);
function effectiveAreaCategories(data) {
    const base = data.areaCategories || [];
    const overrides = (data.areaOverrides || {})[`${selectedDepartment}/${selectedArea}`];
    return applyCascadedCategoryOrder((overrides ? base.map((cat) => (overrides[cat.id] ? { ...cat, submenu: overrides[cat.id] } : cat)) : base).filter((cat) => !isHiddenEmptyCategory(cat)));
}

// Orden de Departamentos, Áreas, Apartados y Pantallas que le toca a esta cuenta: el del Árbol Maestro y, bajando, el de su
// Giro, Plan, Cliente, Administrador, Perfil y Usuario (el más cercano a ella gana; lo calcula el servidor). Una cuenta de
// SaaS no lo usa. Lo que no aparece en una lista conserva su posición de siempre, al final, igual que en el árbol.
let cascadedOrder = null;
async function fetchCascadedOrder() {
    try {
        const res = await fetch('/api/business/permission-order', { credentials: 'include' });
        return res.ok ? await res.json() : null;
    } catch {
        return null;
    }
}
function orderByIds(list, orderIds, idOf) {
    if (!Array.isArray(orderIds) || !orderIds.length) return list;
    const byId = new Map(list.map((item) => [idOf(item), item]));
    const ordered = [];
    orderIds.forEach((id) => {
        if (byId.has(id)) { ordered.push(byId.get(id)); byId.delete(id); }
    });
    list.forEach((item) => { if (byId.has(idOf(item))) ordered.push(item); });
    return ordered;
}
function applyCascadedCategoryOrder(categories) {
    if (!cascadedOrder || !selectedDepartment || !selectedArea) return categories;
    const scope = `${selectedDepartment}::${selectedArea}`;
    return orderByIds(categories, (cascadedOrder.apartadoOrders || {})[scope], (cat) => cat.id).map((cat) => {
        const pantallaOrder = (cascadedOrder.pantallaOrders || {})[`${scope}::${cat.id}`];
        return pantallaOrder && cat.submenu ? { ...cat, submenu: orderByIds(cat.submenu, pantallaOrder, (pantalla) => pantalla.id) } : cat;
    });
}

function applyAreaFilter(data) {
    return {
        ...data,
        sections: data.sections.map((s) => {
            if (s.id !== selectedDepartment) return s;
            return { ...s, items: selectedArea ? effectiveAreaCategories(data) : [] };
        })
    };
}

// "Pantalla habilitada" gate for the department sidebar — runs after
// applyAreaFilter, when `s.items` for the selected department is already
// the flat list of categorías (Catálogos/Operaciones/...) for the
// currently-selected área. Filters each categoría's pantallas down to the
// ones this user's grants actually cover (hasScreenGrant, same 3-tier
// match the permission tree itself uses), then drops any categoría left
// with zero pantallas so an admin restricting a profile doesn't leave a
// dangling empty heading in the sidebar. selectedDepartment/selectedArea
// are read directly (not threaded through `data`) since this only ever
// runs against the currently-selected department's own section.
// Menús desplegables que solo existen en la barra lateral: las pantallas de una categoría que comparten `sidebarGroup` (menu.json) se juntan en un
// menú con el nombre del grupo, cerrado por defecto, para no ver toda la lista cuando no se necesita (Daniel, 2026-10-31: las 7 categorías de
// Catálogos de C. Distribución bajo "Categorías"). El árbol de permisos, Panel y la ruta de arriba siguen con las pantallas sueltas: no cambia ninguna
// llave de permiso. Se arma después del filtro de permisos, así cuenta solo lo que esa persona sí ve; con menos de 2 pantallas visibles no se agrupa.
// minItems: cuántas pantallas visibles hacen falta para que se junten en el grupo (de fábrica 2; el grupo «QR's» sale desde la primera).
const SIDEBAR_GROUPS = {
    categorias: { labelKey: 'menu.catCentroDistCategorias', icon: 'bx-category' },
    qrs: { labelKey: 'menu.opCentroDistQrs', icon: 'bx-qr', minItems: 1 },
    // Operaciones > Mtto. de activos (2026-11-13): Preventivo y Correctivo. Sale desde la primera pantalla que se ve.
    mtto: { labelKey: 'menu.opCentroDistMtto', icon: 'bx-wrench', minItems: 1, abbrKeys: ['menu.opCentroDistMttoAbbr1', 'menu.opCentroDistMttoAbbr2'] },
    // Cargas Manuales > Registros Información (2026-11-25): cada registro (los de siempre y los que agrega el cliente) es una pantalla anidada aquí, con «＋ Agregar nuevo registro» al inicio.
    // Análisis › Análisis fijos: un menú por proceso (hoy Distribución, con Pedidos por sitio).
    anDistribucion: { labelKey: 'menu.anGrupoDistribucion', icon: 'bx-package', minItems: 1 },
    // Análisis › Manuales: el segundo desglose, junto a «Registros Información»: «＋ Nuevo análisis», los análisis y «Todos los análisis».
    analisisReg: { labelKey: 'menu.cmAnalisisRegistros', icon: 'bx-analyse', minItems: 1, abbrKeys: ['menu.cmAnalisisRegistrosAbbr1', 'menu.cmAnalisisRegistrosAbbr2'] },
    registros: { labelKey: 'menu.cmRegistrosInformacion', icon: 'bx-data', minItems: 1, abbrKeys: ['menu.cmRegistrosInformacionAbbr1', 'menu.cmRegistrosInformacionAbbr2'] },
    // Los registros que ya no se usan (los de siempre y los agregados) pasan aquí: se ven, pero ya no reciben cargas (2026-11-26).
    registrosObsoletos: { labelKey: 'menu.cmRegistrosObsoletos', icon: 'bx-archive', minItems: 1, abbrKeys: ['menu.cmRegistrosObsoletosAbbr1'] },
};
function groupSidebarScreens(pantallas, categoryId) {
    const counts = {};
    pantallas.forEach((p) => { if (p.sidebarGroup && SIDEBAR_GROUPS[p.sidebarGroup]) counts[p.sidebarGroup] = (counts[p.sidebarGroup] || 0) + 1; });
    const placed = new Set();
    const out = [];
    pantallas.forEach((p) => {
        const key = p.sidebarGroup;
        if (!key || !SIDEBAR_GROUPS[key] || counts[key] < (SIDEBAR_GROUPS[key].minItems || 2)) { out.push(p); return; }
        if (placed.has(key)) return;
        placed.add(key);
        out.push({
            id: `grp-${categoryId}-${key}`,
            labelKey: SIDEBAR_GROUPS[key].labelKey,
            icon: SIDEBAR_GROUPS[key].icon,
            ...(SIDEBAR_GROUPS[key].abbrKeys ? { abbrKeys: SIDEBAR_GROUPS[key].abbrKeys } : {}),
            href: '#',
            submenu: pantallas.filter((q) => q.sidebarGroup === key),
        });
    });
    return out;
}
// Una pantalla del menú que se muestra también en otra área comparte el permiso de la original (grantFrom: { dept, area, path }): se ve si se tiene ese permiso. Las demás se miden en el área elegida (grantAs = la ruta de otra pantalla de la misma área).
function sidebarScreenAllowed(cat, pantalla) {
    if (pantalla.grantFrom) return hasScreenGrant(pantalla.grantFrom.dept, pantalla.grantFrom.area, pantalla.grantFrom.path);
    return hasScreenGrant(selectedDepartment, selectedArea, `${cat.id}/${pantalla.grantAs || pantalla.id}`);
}
function applyScreenGrantFilter(data) {
    if (!selectedDepartment || !selectedArea) return data;
    return {
        ...data,
        sections: data.sections.map((s) => {
            if (s.id !== selectedDepartment) return s;
            return {
                ...s,
                // Los seis apartados (Catálogos, Operaciones, Admin, Gestión, Reportes y Material de Apoyo) salen SIEMPRE en toda área, aunque esa persona no tenga ninguna pantalla en alguno (Daniel, 2026-11-18): el vacío
                // sale atenuado y sin pantallas (empty), no se esconde.
                items: s.items
                    .map((cat) => {
                        const submenu = groupSidebarScreens((cat.submenu || []).filter((pantalla) => !pantalla.sidebarHidden && (
                            pantalla.permissionOnly || sidebarScreenAllowed(cat, pantalla)
                        )), cat.id);
                        return { ...cat, submenu, empty: !submenu.some((p) => !p.permissionOnly) };
                    })
                    .filter((cat) => !(cat.empty && HIDE_EMPTY_CATEGORIES_IN.has(selectedDepartment))),
            };
        }),
    };
}

// Inicio, Panel y Tablero (los tres de General) de un usuario o perfil del cliente salen solo si se los asignaron en su árbol, como todo lo demás: un usuario recién creado, sin nada asignado, no ve ninguna opción. El
// administrador del cliente sin configuración propia los ve si se los asignó el contrato (hasMainButtonPermission → adminMainCovers) y la cuenta SaaS arma su menú aparte (con sus propios permisos), así que no pasa por aquí.
const MAIN_NAV_ITEM_IDS = ['home', 'panel', 'dashboard'];
function applyMainNavGrantFilter(data) {
    if (currentRole === 'admin') return data;
    return {
        ...data,
        sections: data.sections.map((s) => {
            if (s.id !== 'main') return s;
            return { ...s, items: (s.items || []).filter((i) => !MAIN_NAV_ITEM_IDS.includes(i.id) || hasMainButtonPermission(i.id)) };
        }),
    };
}

// Al cambiar el departamento o el área desde los selectores de arriba, una pantalla que es de otra área ya no va: se sale de ella (a «Panel») para no dejar, por ejemplo, el Layout de C. Distribución abierto estando en Transporte Volumen.
// Solo se llama cuando la persona cambia el selector (no al abrir la pantalla). Las pantallas generales (Inicio, Panel, Configuración) y las que no pertenecen a un área se quedan.
// Al cambiar de departamento o de área, la pantalla abierta se cierra (va a Panel) si ya no es de lo elegido. Hay dos formas de saberlo:
//  1) las pantallas con una sola ruta en SCREEN_GRANT_PATHS: se cierra si su departamento › área no es el elegido;
//  2) las demás pantallas que viven SOLO dentro de áreas (todas las que salen en areaCategories/areaOverrides del menú y no en las secciones generales: p. ej. Alta Artículos, los catálogos, «Pedir alta de código», que existe en
//     cada área): se abrieron «para» el departamento y el área de ese momento (areaOpenedWith, se anota al abrir la página) y se cierran en cuanto cambia cualquiera de los dos. Antes solo cerraban las de (1) y el resto se quedaba abierta.
let areaOpenedWith = null;
let areaOnlyPages = new Set();
function computeAreaOnlyPages(rawMenu) {
    const collect = (node, into) => {
        if (Array.isArray(node)) { node.forEach((n) => collect(n, into)); return; }
        if (node && typeof node === 'object') {
            if (typeof node.href === 'string' && /\.html$/i.test(node.href)) into.add(node.href);
            Object.values(node).forEach((v) => collect(v, into));
        }
    };
    const inAreas = new Set();
    collect(rawMenu && rawMenu.areaCategories, inAreas);
    collect(rawMenu && rawMenu.areaOverrides, inAreas);
    const general = new Set();
    collect(rawMenu && rawMenu.sections, general);
    return new Set([...inAreas].filter((href) => !general.has(href)));
}
function leaveScreenIfOutOfArea() {
    // Pantallas de General (<body data-shell="general">, ver initDashboardInner): se abren sin departamento ni área; en cuanto la persona elige uno de los dos, la pantalla se cierra y se va a Panel, con lo que está operando (Daniel, 2026-11-20).
    if (document.body && document.body.dataset && document.body.dataset.shell === 'general') {
        if (selectedDepartment || selectedArea) location.href = 'Panel.html';
        return;
    }
    const page = document.body && document.body.dataset ? document.body.dataset.activePage : '';
    const grant = page && typeof SCREEN_GRANT_PATHS !== 'undefined' ? SCREEN_GRANT_PATHS[page] : null;
    if (grant) {
        if (grant.sectionId === 'main') return;
        if (grant.sectionId === selectedDepartment && grant.itemId === selectedArea) return;
        location.href = 'Panel.html';
        return;
    }
    // Soporte, Panel, los botones generales y las pantallas de GEIPSA se abren desde fuera de las áreas: no se cierran al cambiar
    if (!page || page === 'support' || page === 'panel' || page.startsWith('btn-') || page.startsWith('admin-')) return;
    const file = (location.pathname.split('/').pop() || '').trim();
    if (!areaOnlyPages.has(file)) return;
    const same = areaOpenedWith && selectedDepartment === areaOpenedWith.department && selectedArea === areaOpenedWith.area;
    if (!same) location.href = 'Panel.html';
}
function renderFilteredMenu() {
    syncPickerCascade();
    if (menuData) renderMenu(applyMainNavGrantFilter(applyScreenGrantFilter(applyAreaFilter(applyDepartmentFilter(menuData)))));
    // Every department/área change (there are several call sites: the
    // dept/area pickers, "defaults" modal, login-defaults auto-apply...)
    // funnels through here, so this is the one place a page like Panel.html
    // needs to listen to react without a full reload — mirrors
    // dashboard:language-changed's own dispatch further up this file.
    document.dispatchEvent(new CustomEvent('dashboard:area-changed', {
        detail: { department: selectedDepartment, area: selectedArea },
    }));
}

// Panel.html's own data source: every categoría (Catálogos/Operaciones/
// Admin/Gestión/Reportes/Material Apoyo) for the CURRENTLY selected
// departamento/área, each with its submenu narrowed down to real,
// grant-covered pantallas only (permissionOnly leaves and href="#"
// placeholders dropped, same hasScreenGrant check the sidebar itself
// uses) -- unlike applyScreenGrantFilter, a categoría that ends up with
// zero pantallas is kept (not dropped) so Panel can still show it with a
// 0 count instead of silently disappearing.
function getPanelCategories() {
    if (!menuData || !selectedDepartment || !selectedArea) return [];
    const categories = effectiveAreaCategories(menuData).map((cat) => ({
        ...cat,
        submenu: (cat.submenu || []).filter((s) => (
            !s.permissionOnly && s.href && s.href !== '#'
            && sidebarScreenAllowed(cat, s)
        )),
    }));
    return HIDE_EMPTY_CATEGORIES_IN.has(selectedDepartment) ? categories.filter((cat) => cat.submenu.length) : categories;
}

// Most areas' full names are already short enough to show as-is; a few
// (e.g. "ISO 9001:2015 Sistema de Gestión de Calidad") are long enough to
// need a dedicated abbreviation instead of just truncating with ellipsis —
// abbrKey is optional and falls back to the full name when not set.
function updateAreaPickerLabel() {
    const label = document.getElementById('area-picker-label');
    if (!label) return;
    const areas = availableAreasForDepartment(selectedDepartment);
    const area = areas.find((a) => a.key === selectedArea);
    label.textContent = area ? t(area.abbrKey || area.labelKey, area.labelParams || {}) : t('sidebar.area');
    document.querySelectorAll('.area-option').forEach((btn) => {
        btn.classList.toggle('active', btn.dataset.area === selectedArea);
    });
}

// Rebuilt (not just relabeled) whenever the department or language changes,
// since the list of areas itself depends on which department is selected.
function renderAreaPickerOptions() {
    const dropdown = document.getElementById('area-picker-dropdown');
    if (!dropdown) return;
    dropdown.innerHTML = '';
    const areas = availableAreasForDepartment(selectedDepartment);
    areas.forEach((area) => {
        const li = document.createElement('li');
        li.setAttribute('role', 'none');
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.setAttribute('role', 'menuitem');
        btn.className = 'dept-option area-option';
        btn.dataset.area = area.key;
        const icon = document.createElement('i');
        icon.className = `bx ${area.icon}`;
        icon.setAttribute('aria-hidden', 'true');
        const span = document.createElement('span');
        span.textContent = t(area.labelKey, area.labelParams || {});
        btn.appendChild(icon);
        btn.appendChild(span);
        li.appendChild(btn);
        dropdown.appendChild(li);
    });
    updateAreaPickerLabel();
}

// Also auto-picks the department's one area for the user when there's
// nothing to actually choose between — same idea as the department picker
// hiding itself when the client only has one contracted module.
function updateAreaPickerVisibility() {
    const picker = document.getElementById('area-picker');
    if (!picker || currentRole === 'admin') return;
    const areas = availableAreasForDepartment(selectedDepartment);
    if (areas.length === 1) {
        if (selectedArea !== areas[0].key) {
            selectedArea = areas[0].key;
            localStorage.setItem('area', selectedArea);
            renderAreaPickerOptions();
            renderFilteredMenu();
        }
        picker.classList.add('dept-picker-disabled');
        return;
    }
    picker.classList.toggle('dept-picker-disabled', areas.length === 0);
}

// Shows only the abbreviation once a department is picked (e.g. "FIN"),
// not the full name — same compact-pill treatment as Cost Centers, now that
// this lives in the top bar instead of the sidebar. Falls back to the
// generic placeholder word when nothing is selected yet.
function updateDeptPickerLabel() {
    const label = document.getElementById('dept-picker-label');
    if (!label) return;
    const dept = availableDepartments.find((d) => d.key === selectedDepartment);
    label.textContent = dept ? t(dept.abbrKey) : t('sidebar.department');
    document.querySelectorAll('.dept-option').forEach((btn) => {
        btn.classList.toggle('active', btn.dataset.dept === selectedDepartment);
    });
}

// A submenu only counts as real, clickable navigation if at least one entry
// is an actual destination -- neither a classification band (isClassification,
// e.g. "Control Interno") nor a permission-only leaf (a column/button that
// exists solely to be granted in Accesos y Permisos, see PermissionTree.js).
// A pantalla like Carga Combustible/Nuestros Traslados always HAS a submenu
// (its own column list, for permission granularity), but that submenu is
// 100% classification/permission metadata -- it must render as a plain link
// to its own href, not an expandable dropdown with nothing real inside.
function hasNavigableChildren(submenu) {
    return (submenu || []).some((s) => !s.isClassification && !s.permissionOnly);
}

function buildSubmenu(items) {
    const ul = document.createElement('ul');
    ul.className = 'sub-menu';
    items.forEach((item) => {
        const li = document.createElement('li');
        if (item.addNew) li.classList.add('sub-menu-add'); // «＋ Agregar nuevo …»: opción con borde punteado dentro del desplegable
        if (item.dimmed) li.classList.add('sub-menu-off'); // un registro desactivado (solo lo ve quien puede crear): atenuado
        const a = document.createElement('a');
        a.href = item.href || '#';
        a.className = 'sub-menu-link';
        if (item.icon) {
            const icon = document.createElement('i');
            icon.className = `bx ${item.icon}`;
            icon.setAttribute('aria-hidden', 'true');
            a.appendChild(icon);
        }
        const span = document.createElement('span');
        // item.label (literal) wins over labelKey — same runtime-injected-
        // item convention as buildMenuItem/crumbFromItem (see their own
        // comments). Without this fallback, an injected item with no
        // labelKey at all (e.g. a saved report) would throw here (t() calls
        // .split on its key argument, which crashes on undefined) instead
        // of just rendering blank.
        const fullLabel = item.label || t(item.labelKey, item.labelParams || {});
        span.textContent = fullLabel;
        // Same Modo ayuda fix as buildMenuItem's own aria-label above -- a
        // sub-menu row had no name of its own either.
        a.setAttribute('aria-label', fullLabel);
        a.setAttribute('data-help-key', 'sidebarNavigation');
        // abbrKeys (see buildSidebarData's admin-business-sectors entry for
        // the first real user) — a ladder of progressively shorter labels,
        // longest first. Stashed as data instead of resolved once here
        // because applySubmenuAbbreviations (below) re-measures on every
        // resize, and the sidebar's language can change without a full
        // menu rebuild (see dashboard:language-changed).
        if (item.abbrKeys?.length) {
            span.dataset.abbrLadder = JSON.stringify([fullLabel, ...item.abbrKeys.map((k) => t(k))]);
        }
        a.appendChild(span);
        li.appendChild(a);
        // A sub-menu item can itself hold its own nested submenu (e.g.
        // Reportes > Personalizados > each saved report) — same
        // dropdown/chevron treatment as a top-level item (buildMenuItem),
        // just one level deeper. menu-item-dropdown reuses the existing
        // click-to-toggle wiring in wireMenuInteractions() as-is, which
        // already supports arbitrary nesting depth via :scope > .sub-menu.
        if (hasNavigableChildren(item.submenu)) {
            li.classList.add('menu-item-dropdown', 'sub-menu-item-dropdown');
            const chevron = document.createElement('i');
            chevron.className = 'bx bx-chevron-down';
            chevron.setAttribute('aria-hidden', 'true');
            a.appendChild(chevron);
            li.appendChild(buildSubmenu(item.submenu));
        }
        ul.appendChild(li);
    });
    return ul;
}

function buildMenuItem(item) {
    const li = document.createElement('li');
    const navigable = hasNavigableChildren(item.submenu);
    li.className = 'menu-item' + (navigable ? ' menu-item-dropdown' : ' menu-item-static');
    if (item.active) li.classList.add('active');
    // Un apartado de un área sin ninguna pantalla para esta persona (applyScreenGrantFilter) se queda visible pero atenuado y sin ir a ningún lado.
    if (item.empty) li.classList.add('menu-item-empty');

    const a = document.createElement('a');
    a.href = item.href || '#';
    a.className = 'menu-link';
    if (item.empty) {
        a.setAttribute('aria-disabled', 'true');
        a.addEventListener('click', (event) => event.preventDefault());
    }

    const icon = document.createElement('i');
    icon.className = `bx ${item.icon}`;
    icon.setAttribute('aria-hidden', 'true');
    a.appendChild(icon);

    const span = document.createElement('span');
    // item.label (literal) wins over labelKey when both could apply — only
    // ever set for runtime-injected items whose text is free-form client
    // data (e.g. a saved report's own name), never a translatable string.
    const fullLabel = item.label || t(item.labelKey, item.labelParams || {});
    span.textContent = fullLabel;
    // The FULL label, not whatever abbrKeys shortens the visible span to --
    // this is also this link's own name for Modo ayuda (findHelpModeContent
    // reads aria-label before ever considering a distant ancestor's own).
    // Confirmed live, 2026-09-30: without this, clicking any sidebar item
    // (Inicio, a group header like "Config. SaaS", any submenu row) walked
    // all the way up to <nav aria-label="Main navigation"> instead, since
    // .menu-link/.sub-menu-link never had a name of their own at all.
    a.setAttribute('aria-label', fullLabel);
    a.setAttribute('data-help-key', 'sidebarNavigation');
    // abbrKeys -- same progressively-shorter-label ladder as buildSubmenu's
    // own abbrLadder (see applySubmenuAbbreviations), just for a top-level
    // item instead of a nested one. A top-level item with no abbrKeys still
    // gets plain CSS ellipsis (see .menu-link span in Inicio-en.css) and the
    // hover tooltip below whenever its label actually overflows.
    if (item.abbrKeys?.length) {
        span.dataset.abbrLadder = JSON.stringify([fullLabel, ...item.abbrKeys.map((k) => t(k))]);
    }
    a.appendChild(span);

    if (navigable) {
        const chevron = document.createElement('i');
        chevron.className = 'bx bx-chevron-down';
        chevron.setAttribute('aria-hidden', 'true');
        a.appendChild(chevron);
    }

    li.appendChild(a);
    if (navigable) {
        li.appendChild(buildSubmenu(item.submenu.filter((sm) => !sm.permissionOnly)));
    }
    return li;
}

// Mirrors "Administración del Negocio" (sidebar) into its own accordion
// group in the top-bar Settings dropdown, right below Style, so its items
// (Servicio Contratado, Roles, Datos de Cliente, etc.) are reachable from
// there too. Hidden whenever there's no admin-business item to show (GEIPSA
// admin's reduced sidebar has none).
// A PURE folder (no real href of its own, e.g. Servicio Contratado) becomes
// its own 2-click accordion here — collapsed by default, opened by its own
// toggle, exactly like the main sidebar's nested dropdowns (buildSubmenu) —
// per explicit user request to match that behavior instead of the flat
// always-expanded heading this used to be.
// A leaf (real href, e.g. Nuestros Centros Costos, Roles, or Expansiones —
// href="#" there just means "not built yet", not "this is a folder") is
// always its own plain row, even if it also carries a submenu of its own
// (the permission tree's column list, ccCode/ccName/... -- not sub-nav).
function buildBusinessAdminSubmenuList(items) {
    const ul = document.createElement('ul');
    ul.className = 'settings-submenu';
    ul.setAttribute('role', 'menu');
    (items || []).filter((i) => !i.permissionOnly).forEach((item) => {
        const hasRealHref = item.href && item.href !== '#';
        const navigableChildren = (item.submenu || []).filter((c) => !c.permissionOnly);
        const li = document.createElement('li');
        li.setAttribute('role', 'none');
        if (!hasRealHref && navigableChildren.length) {
            li.className = 'settings-submenu-group';
            const toggleBtn = document.createElement('button');
            toggleBtn.type = 'button';
            toggleBtn.className = 'settings-submenu-toggle';
            toggleBtn.setAttribute('aria-expanded', 'false');
            if (item.icon) {
                const icon = document.createElement('i');
                icon.className = `bx ${item.icon}`;
                icon.setAttribute('aria-hidden', 'true');
                toggleBtn.appendChild(icon);
            }
            const label = document.createElement('span');
            label.textContent = t(item.labelKey, item.labelParams || {});
            toggleBtn.appendChild(label);
            const chevron = document.createElement('i');
            chevron.className = 'bx bx-chevron-down';
            chevron.setAttribute('aria-hidden', 'true');
            toggleBtn.appendChild(chevron);
            li.appendChild(toggleBtn);
            li.appendChild(buildBusinessAdminSubmenuList(navigableChildren));
        } else {
            const a = document.createElement('a');
            a.href = item.href || '#';
            a.setAttribute('role', 'menuitem');
            if (item.icon) {
                const icon = document.createElement('i');
                icon.className = `bx ${item.icon}`;
                icon.setAttribute('aria-hidden', 'true');
                a.appendChild(icon);
            }
            const label = document.createElement('span');
            label.textContent = t(item.labelKey, item.labelParams || {});
            a.appendChild(label);
            li.appendChild(a);
        }
        ul.appendChild(li);
    });
    return ul;
}

// Wires each direct toggle inside `root` (not its own nested toggles —
// those get wired by the recursive call on their own list) to expand/
// collapse just its own nested <ul>, then re-measures the "Administración
// del Negocio" group's own fixed pixel height if it's currently open —
// that height was fixed at whatever this nested list's collapsed size was
// when the OUTER group was last opened, so it clips/gaps around this
// toggle otherwise (same fix as wireMenuInteractions' own ancestor
// re-measure, one level up).
function wireSettingsSubmenuToggles(root) {
    root.querySelectorAll(':scope > li > .settings-submenu-toggle').forEach((toggleBtn) => {
        const li = toggleBtn.closest('li');
        const nested = li.querySelector(':scope > ul');
        wireSettingsSubmenuToggles(nested);
        toggleBtn.addEventListener('click', (event) => {
            event.stopPropagation();
            const isOpen = li.classList.toggle('open');
            toggleBtn.setAttribute('aria-expanded', String(isOpen));
            nested.style.height = isOpen ? `${nested.scrollHeight}px` : '0';
            const ancestorGroup = document.getElementById('business-admin-group');
            const ancestorSubmenu = document.getElementById('business-admin-submenu');
            if (ancestorGroup?.classList.contains('open') && ancestorSubmenu) {
                ancestorSubmenu.style.height = 'auto';
                ancestorSubmenu.style.height = `${ancestorSubmenu.scrollHeight}px`;
            }
        });
    });
}

function renderBusinessAdminSettingsMenu(items) {
    const group = document.getElementById('business-admin-group');
    const submenu = document.getElementById('business-admin-submenu');
    if (!group || !submenu) return;
    submenu.innerHTML = '';
    const navigable = (items || []).filter((i) => !i.permissionOnly);
    if (!navigable.length) {
        group.hidden = true;
        return;
    }
    const built = buildBusinessAdminSubmenuList(navigable);
    while (built.firstChild) submenu.appendChild(built.firstChild);
    wireSettingsSubmenuToggles(submenu);
    group.hidden = false;
}

function renderMenu(data) {
    const mount = document.getElementById('menu-mount');
    mount.innerHTML = '';

    data.sections.forEach((section) => {
        // Items flagged permissionOnly (e.g. the top-bar button shortcuts
        // under "Iconos y Botones" / "General") exist purely to be granted
        // in Accesos y Permisos — they're not real navigation, so they never
        // render here even though PermissionTree.js still lists them.
        let items = (section.items || []).filter((i) => !i.permissionOnly);
        // "Administración del Negocio" no longer gets its own sidebar
        // shortcut — it's reachable from the top-bar Settings dropdown
        // instead (renderBusinessAdminSettingsMenu below), so just drop it
        // from the regular item list here.
        if (section.id === 'main') {
            const adminBusinessItem = items.find((i) => i.id === 'admin-business');
            if (adminBusinessItem) {
                items = items.filter((i) => i.id !== 'admin-business');
            }
            renderBusinessAdminSettingsMenu(adminBusinessItem?.submenu);
        }
        const ul = document.createElement('ul');
        ul.className = 'menu';
        ul.dataset.sectionId = section.id;
        items.forEach((item) => ul.appendChild(buildMenuItem(item)));
        mount.appendChild(ul);
    });

    const footerMount = document.getElementById('footer-menu-mount');
    footerMount.innerHTML = '';
    data.footer.forEach((item) => {
        const li = document.createElement('li');
        li.className = 'menu-item menu-item-static';
        const a = document.createElement('a');
        a.href = item.href || '#';
        a.className = 'menu-link';
        const icon = document.createElement('i');
        icon.className = `bx ${item.icon}`;
        icon.setAttribute('aria-hidden', 'true');
        const span = document.createElement('span');
        span.textContent = t(item.labelKey);
        a.append(icon, span);
        li.appendChild(a);
        footerMount.appendChild(li);
    });

    // Sin ninguna opción en el menú (por ejemplo una cuenta recién creada, sin nada asignado) tampoco sale el buscador: no habría nada que buscar.
    const searchBox = document.querySelector('.menu-container .search');
    if (searchBox) searchBox.style.display = mount.querySelector('.menu-link, .sub-menu-link') ? '' : 'none';

    wireMenuInteractions();
    applySubmenuAbbreviations();
}

// A label with its own abbrLadder (see buildSubmenu/buildMenuItem) steps
// down through progressively shorter versions of itself -- longest that
// still fits the sidebar's own fixed expanded width wins -- instead of
// jumping straight to CSS ellipsis. Covers both nested (.sub-menu-link)
// and top-level (.menu-link) items -- same rule everywhere in the
// sidebar, not just wherever abbrKeys happened to be added first. Re-run
// on resize/collapse-toggle since the sidebar's available width isn't
// otherwise re-checked once rendered; harmless to call for a menu with no
// abbreviated items (the selector just matches nothing).
// scrollWidth y clientWidth son enteros: un texto que se pasa por menos de 1 px (95.4 en una caja de 95.2) parece caber y aun así se corta con "…".
// Se compara también el ancho real del texto con el de la caja.
function submenuSpanFits(span) {
    if (span.scrollWidth > span.clientWidth) return false;
    const range = document.createRange();
    range.selectNodeContents(span);
    return range.getBoundingClientRect().width <= span.getBoundingClientRect().width + 0.05;
}
// Regla de todo el sistema (Daniel, 2026-11-19): si un nombre no cabe, se ABREVIA; no se corta con «…». Los nombres que ya traen su escalera (abbrKeys en menu.json) usan esa; los que no la traen (por ejemplo los
// 10 niveles de Implementación Inicial, «3 · Estructura de organización») se abrevian solos: primero las palabras largas (de la más larga a la más corta: «Estruc. de organización», «Estruc. de Org.»), luego sin conectores
// y al final solo las primeras palabras. El nombre completo se ve igual que en los demás: con la barra cerrada al pasar el mouse, en la ruta de arriba y en Modo ayuda.
const AUTO_ABBR_CONNECTORS = new Set(['de', 'del', 'la', 'las', 'los', 'el', 'y', 'e', 'o', 'u', 'para', 'por', 'en', 'al', 'con', 'of', 'the', 'and', 'for', 'to', 'in', 'on', 'at', 'with']);
function autoAbbrLadder(full, options) {
    const numbered = /^(\s*\d+\s*[·.\-:)]\s*)([\s\S]*)$/.exec(full); // «3 · Estructura…»: el número de adelante se queda
    const prefix = numbered ? numbered[1] : '';
    let words = (numbered ? numbered[2] : full).split(/\s+/).filter(Boolean);
    const ladder = [full];
    const push = (list) => {
        const text = prefix + list.join(' ');
        if (text.length < ladder[ladder.length - 1].length) ladder.push(text);
    };
    // 1) palabras largas abreviadas con punto, la más larga primero (a igual largo, la de más a la derecha)
    const longest = words.map((w, i) => i).filter((i) => Array.from(words[i]).length >= 7 && /^[\p{L}\p{M}]+$/u.test(words[i])).sort((a, b) => Array.from(words[b]).length - Array.from(words[a]).length || b - a);
    // la abreviatura corta la palabra más o menos a la mitad y termina en consonante (Estructura → Estruc., organización → organiz., Asignación → Asign., Conectividad → Conect.)
    const isVowel = (ch) => /[aeiouáéíóúü]/i.test(ch);
    const abbreviate = (word) => {
        const letters = Array.from(word);
        let n = Math.max(4, Math.ceil(letters.length * 0.55));
        while (n > 4 && isVowel(letters[n - 1])) n -= 1;
        while (n < letters.length - 2 && isVowel(letters[n - 1])) n += 1;
        return `${letters.slice(0, n).join('')}.`;
    };
    longest.forEach((i) => {
        words = words.slice();
        words[i] = abbreviate(words[i]);
        push(words);
    });
    // 2) sin conectores (menos el primero)
    const noConnectors = words.filter((w, i) => i === 0 || !AUTO_ABBR_CONNECTORS.has(w.toLowerCase()));
    if (noConnectors.length !== words.length) { words = noConnectors; push(words); }
    // 3) solo las primeras palabras (los datos de una tabla no llegan aquí: «Claude Verify Admin» no puede quedar como «Claude»; ahí el último recurso es el «…» de siempre)
    if (!(options && options.keepWords)) for (let n = words.length - 1; n >= 1; n -= 1) push(words.slice(0, n));
    return ladder;
}
// «Mi App» (TI › Configuración Compañía) se llama «Mi App + nombre corto del cliente» en la barra, en la ruta y en la pestaña (pedido de Daniel, 2026-11-18). El nombre corto sale de GET /api/business/mi-app/name,
// se pide una sola vez por sesión (se recuerda 10 minutos en este navegador, por cliente) y solo si la persona tiene la pantalla en su barra. Se cambia labelKey/labelParams del nodo (no un texto fijo) para que siga el idioma.
const MI_APP_NODE_ID = 'cat-operaciones-ti-cc-mi-app';
const MI_APP_NAME_TTL_MS = 10 * 60 * 1000;
function miAppNameCacheKey() { return currentUser && currentUser.clientId ? `sgnMiAppName:${currentUser.clientId}` : ''; }
function readMiAppNameCache() {
    const key = miAppNameCacheKey();
    if (!key) return null;
    try {
        const saved = JSON.parse(sessionStorage.getItem(key) || 'null');
        return saved && typeof saved.name === 'string' && Date.now() - saved.at < MI_APP_NAME_TTL_MS ? saved.name : null;
    } catch { return null; }
}
function labelMiAppNode(data, name) {
    if (!data || !name) return false;
    let found = false;
    const walk = (value) => {
        if (!value || typeof value !== 'object') return;
        if (Array.isArray(value)) { value.forEach(walk); return; }
        if (value.id === MI_APP_NODE_ID) { value.labelKey = 'menu.ccMiAppNamed'; value.labelParams = { name }; found = true; }
        Object.values(value).forEach(walk);
    };
    walk(data);
    return found;
}
async function syncMiAppLabel() {
    const key = miAppNameCacheKey();
    if (!key || readMiAppNameCache() !== null) return;
    if (!document.querySelector('#Sidebar a[href="OpTIMiApp.html"]')) return; // sin la pantalla en su barra no hay etiqueta que poner
    let name = '';
    try {
        const res = await fetch('/api/business/mi-app/name', { credentials: 'include' });
        if (res.ok) name = String((await res.json()).name || '');
    } catch { return; }
    try { sessionStorage.setItem(key, JSON.stringify({ name, at: Date.now() })); } catch { /* sin almacenamiento: se pide de nuevo la próxima vez */ }
    if (labelMiAppNode(menuData, name)) { renderFilteredMenu(); renderBreadcrumbBar(); }
}
function applySubmenuAbbreviations() {
    // los nombres sin escalera propia que no caben reciben la automática (se guarda para que el redibujo al cambiar el ancho la siga usando)
    document.querySelectorAll('.sub-menu-link > span:first-of-type:not([data-abbr-ladder]), .menu-link > span:first-of-type:not([data-abbr-ladder])').forEach((span) => {
        if (!span.textContent || submenuSpanFits(span)) return;
        const ladder = autoAbbrLadder(span.textContent);
        if (ladder.length > 1) span.dataset.abbrLadder = JSON.stringify(ladder);
    });
    document.querySelectorAll('.sub-menu-link span[data-abbr-ladder], .menu-link span[data-abbr-ladder]').forEach((span) => {
        const ladder = JSON.parse(span.dataset.abbrLadder);
        for (const text of ladder) {
            span.textContent = text;
            if (submenuSpanFits(span)) return;
        }
        // Nothing in the ladder fit -- left on the shortest step, which
        // still ellipsizes via the same CSS every other sub-menu label
        // already relies on.
    });
}
window.addEventListener('resize', applySubmenuAbbreviations);

// --- Tablas: si un nombre no cabe en su columna, se abrevia (regla de todo el sistema, Daniel 2026-11-19: «si algo no cabe se abrevia, y al sobreponer ya se ve el nombre real completo») ---
// Aplica a los ENCABEZADOS de cada .data-table y a las celdas de texto sencillo (nombres, descripciones). El texto de verdad NO se toca: se queda en la celda, así los filtros, el orden, el copiar y el exportar lo siguen leyendo
// completo; solo cambia lo que se VE (CSS de Inicio-en.css: data-abbr dibuja la abreviatura encima del texto, que se vuelve transparente). El nombre completo sale al sobreponer (title). Se mide con un canvas (con la misma
// letra, tamaño, mayúsculas y espaciado de la celda) y sin tocar el diseño por celda, así una tabla de mil renglones no se traba. Las celdas con números, fechas, códigos, correos o botones no se abrevian (un dato no se
// acorta como un nombre): si ni abreviado cabe, queda el «…» de siempre. Lo vuelve a revisar cuando cambia el ancho de una columna (arrastrar, ventana, barra lateral), el tamaño de letra, el idioma o los renglones.
const TABLE_ABBR_TEXT_RE = /^[\p{L}][\p{L}\p{M}\s.,&'’()·-]*$/u;
const tableAbbrCtx = document.createElement('canvas').getContext('2d');
const tableAbbrWidths = new Map();
const tableAbbrLadders = new Map();
const dataTableAbbrQueued = new Set();
function tableAbbrSpec(el) {
    const cs = getComputedStyle(el);
    const spacing = parseFloat(cs.letterSpacing) || 0;
    // un encabezado lleva botones dentro de su línea (el ⋮ del formato): el texto solo dispone de lo que ellos dejan (los que van flotando, como el embudo, ya tienen su lugar en el relleno)
    let reserved = 0;
    if (el.tagName === 'TH') {
        Array.from(el.children).forEach((c) => {
            const p = getComputedStyle(c);
            if (p.position === 'absolute' || p.position === 'fixed' || p.display === 'none') return;
            reserved += c.offsetWidth + (parseFloat(p.marginLeft) || 0) + (parseFloat(p.marginRight) || 0);
        });
    }
    const avail = el.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0) - reserved;
    // solo donde el texto de verdad se corta con «…»: una línea, escondiendo lo que sobra (el historial, por ejemplo, parte sus textos en líneas)
    const skip = cs.whiteSpace !== 'nowrap' || cs.overflowX !== 'hidden' || avail <= 0;
    return { skip, avail, spacing, upper: cs.textTransform === 'uppercase', font: `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}` };
}
function tableAbbrWidth(spec, text) {
    const shown = spec.upper ? text.toUpperCase() : text;
    const key = `${spec.font}|${spec.spacing}|${shown}`;
    let width = tableAbbrWidths.get(key);
    if (width === undefined) {
        if (tableAbbrWidths.size > 30000) tableAbbrWidths.clear();
        tableAbbrCtx.font = spec.font;
        width = tableAbbrCtx.measureText(shown).width + spec.spacing * Array.from(shown).length;
        tableAbbrWidths.set(key, width);
    }
    return width;
}
// { step: la abreviatura que cabe | null, clipped: true si ni abreviado cabe (queda el «…» de siempre, pero el nombre completo sale al sobreponer) }.
const TABLE_ABBR_NONE = { step: null, clipped: false };
function tableAbbrFor(text, spec, keepWords) {
    if (!text || !spec || spec.skip || tableAbbrWidth(spec, text) <= spec.avail) return TABLE_ABBR_NONE;
    const key = `${keepWords ? 1 : 0}|${text}`;
    let ladder = tableAbbrLadders.get(key);
    if (!ladder) {
        if (tableAbbrLadders.size > 20000) tableAbbrLadders.clear();
        ladder = autoAbbrLadder(text, { keepWords });
        tableAbbrLadders.set(key, ladder);
    }
    for (let i = 1; i < ladder.length; i += 1) if (tableAbbrWidth(spec, ladder[i]) <= spec.avail) return { step: ladder[i], clipped: false };
    return { step: null, clipped: true };
}
function abbreviateDataTableTexts(tableId) {
    const state = dataTableColumnState.get(tableId);
    const table = state && state.table;
    if (!table || !table.isConnected || !table.offsetParent) return; // una tabla escondida (un diálogo cerrado) se revisa al abrirse: sus encabezados cambian de tamaño
    const headerRow = getHeaderRow(table);
    if (!headerRow) return;
    // 1) lecturas (todas juntas: escribir en medio obligaría al navegador a recalcular el diseño una y otra vez)
    const heads = Array.from(headerRow.cells).filter((th) => th.dataset.col).map((th) => {
        if (state.abbrResizeObserver) state.abbrResizeObserver.observe(th);
        const node = Array.from(th.childNodes).find((n) => n.nodeType === 3 && n.nodeValue.trim());
        return { el: th, text: node ? node.nodeValue.trim() : '', spec: tableAbbrSpec(th) };
    });
    // las bandas de arriba («Control Interno», la pantalla de origen) también son nombres
    const bands = Array.from(table.tHead ? table.tHead.querySelectorAll('tr.data-table-group-band th') : []).map((th) => {
        if (state.abbrResizeObserver) state.abbrResizeObserver.observe(th);
        const node = Array.from(th.childNodes).find((n) => n.nodeType === 3 && n.nodeValue.trim());
        return { el: th, text: node && Array.from(th.childNodes).filter((n) => !(n.nodeType === 1 && n.classList.contains('data-table-band-toggle'))).length === 1 ? node.nodeValue.trim() : '', spec: tableAbbrSpec(th) };
    });
    const rows = table.tBodies[0] ? Array.from(table.tBodies[0].rows) : [];
    const colSpecs = new Map();
    for (let i = 0; i < rows.length && i < 60 && colSpecs.size < heads.length; i += 1) {
        if (rows[i].hidden || rows[i].querySelector('td.data-table-empty-cell')) continue;
        Array.from(rows[i].cells).forEach((td) => { if (td.dataset.col && !colSpecs.has(td.dataset.col) && td.clientWidth > 0) colSpecs.set(td.dataset.col, tableAbbrSpec(td)); });
    }
    // Solo se revisa lo que cambió: una columna cuyo ancho o letra es el de la vez anterior no se vuelve a medir en los renglones que ya se vieron (una tabla de mil renglones que se llena por tandas, o una
    // columna que se arrastra, no repite el trabajo de todo lo demás). Un renglón nuevo o cuyo contenido cambió (state.abbrDirty) se revisa completo.
    const sigs = state.abbrSigs || (state.abbrSigs = new Map());
    const seen = state.abbrSeen || (state.abbrSeen = new WeakSet());
    const dirty = state.abbrDirty || new Set();
    state.abbrDirty = new Set();
    const changed = new Set();
    colSpecs.forEach((spec, key) => {
        const sig = `${spec.skip}|${spec.avail}|${spec.font}|${spec.spacing}`;
        if (sigs.get(key) !== sig) { changed.add(key); sigs.set(key, sig); }
    });
    // 2) decisiones (sin tocar el diseño) y 3) escrituras
    const writes = [];
    const forceShort = !!(state.look && state.look.habr); // «Abreviar» (Títulos): los encabezados van siempre en su forma corta (palabras largas con punto y sin conectores, sin cortar palabras); si ni así caben, sigue la escalera de siempre
    const decide = (el, text, spec, keepWords, short) => {
        let { step, clipped } = tableAbbrFor(text, spec, keepWords);
        if (short && text) { const l = autoAbbrLadder(text, { keepWords: true }); const form = l[l.length - 1]; if (form.length < text.length && (step === null || form.length < step.length)) step = form; }
        const wantTitle = step !== null || clipped;
        const same = step === null
            ? el.dataset.abbr === undefined && (wantTitle ? el.dataset.abbrFull === text : el.dataset.abbrTitle === undefined)
            : el.dataset.abbr === step && el.dataset.abbrFull === text;
        if (!same) writes.push([el, step, text, wantTitle]);
    };
    heads.forEach((h) => decide(h.el, h.text, h.spec, false, forceShort));
    bands.forEach((b) => decide(b.el, b.text, b.spec, false));
    rows.forEach((tr) => {
        const fresh = !seen.has(tr) || dirty.has(tr);
        seen.add(tr);
        if (!fresh && !changed.size) return;
        Array.from(tr.cells).forEach((td) => {
            if (!fresh && !changed.has(td.dataset.col)) return;
            const spec = colSpecs.get(td.dataset.col);
            const plain = spec && td.childNodes.length === 1 && td.firstChild.nodeType === 3 && !td.classList.contains('data-table-empty-cell') && !td.classList.contains('editable-cell');
            const text = plain ? td.firstChild.nodeValue.trim() : '';
            decide(td, plain && TABLE_ABBR_TEXT_RE.test(text) ? text : '', spec, true);
        });
    });
    writes.forEach(([el, step, text, wantTitle]) => {
        if (step === null) delete el.dataset.abbr; else el.dataset.abbr = step;
        if (wantTitle) {
            el.dataset.abbrFull = text;
            if (!el.hasAttribute('title') || el.dataset.abbrTitle) { const own = el.dataset.abbrOwn; el.title = own ? text + '\n' + own : text; el.dataset.abbrTitle = '1'; }
            // un encabezado que ya traía su propio texto al sobreponer (una columna «la más reciente»: «Hoy trae…») lo conserva y le suma el nombre completo (Daniel, 2026-11-27)
            else if (el.tagName === 'TH') { el.dataset.abbrOwn = el.title; el.title = text + '\n' + el.title; el.dataset.abbrTitle = '1'; }
        } else {
            delete el.dataset.abbrFull;
            if (el.dataset.abbrTitle) { if (el.dataset.abbrOwn !== undefined) { el.title = el.dataset.abbrOwn; delete el.dataset.abbrOwn; } else el.removeAttribute('title'); delete el.dataset.abbrTitle; }
        }
    });
}
function scheduleDataTableAbbreviation(tableId) {
    if (dataTableAbbrQueued.has(tableId)) return;
    dataTableAbbrQueued.add(tableId);
    // setTimeout y no requestAnimationFrame: una pestaña en segundo plano no dibuja cuadros y la revisión se quedaría esperando
    setTimeout(() => {
        dataTableAbbrQueued.delete(tableId);
        try { abbreviateDataTableTexts(tableId); refreshHeaderAutoAlign(tableId); } catch (err) { console.warn('Abreviar tabla:', err); }
    }, 40);
}
// Una columna cambió su «Ajustar texto» o su alineación (FlexFormat.js): se vuelve a revisar lo que se abrevia y la alineación de «Como los datos».
function refreshTableLook(table) {
    dataTableColumnState.forEach((state, tableId) => { if (state.table === table) scheduleDataTableAbbreviation(tableId); });
}
function scheduleAllDataTableAbbreviations() {
    dataTableColumnState.forEach((state, tableId) => scheduleDataTableAbbreviation(tableId));
}
// Una vez por tabla: se vuelve a revisar cuando cambia el tamaño de un encabezado (arrastrar una columna, la ventana, la barra lateral) o el contenido de la tabla (renglones nuevos, un dato que se edita).
function watchDataTableAbbreviation(tableId) {
    const state = dataTableColumnState.get(tableId);
    if (!state || !state.table || state.abbrWatched) return;
    state.abbrWatched = true;
    const schedule = () => scheduleDataTableAbbreviation(tableId);
    state.abbrResizeObserver = new ResizeObserver(schedule);
    state.abbrDirty = new Set();
    new MutationObserver((mutations) => {
        for (const m of mutations) {
            const el = m.target.nodeType === 1 ? m.target : m.target.parentElement;
            const tr = el && el.closest ? el.closest('tr') : null;
            if (tr && tr.parentElement && tr.parentElement.tagName === 'TBODY') state.abbrDirty.add(tr);
        }
        schedule();
    }).observe(state.table, { childList: true, subtree: true, characterData: true });
    schedule();
}
window.addEventListener('resize', scheduleAllDataTableAbbreviations);
document.addEventListener('dashboard:language-changed', () => setTimeout(scheduleAllDataTableAbbreviations, 0));
// Las medidas dependen de que la letra de la tabla ya esté cargada: cuando termina de cargar, lo medido antes se olvida y se revisa todo otra vez.
function remeasureAllDataTableAbbreviations() {
    tableAbbrWidths.clear();
    dataTableColumnState.forEach((state) => { if (state.abbrSigs) state.abbrSigs.clear(); });
    scheduleAllDataTableAbbreviations();
}
if (document.fonts) {
    if (document.fonts.ready) document.fonts.ready.then(remeasureAllDataTableAbbreviations);
    if (document.fonts.addEventListener) document.fonts.addEventListener('loadingdone', remeasureAllDataTableAbbreviations);
}

// --- Menu interactions (dropdowns, minimize, mobile) ------------------------
function wireMenuInteractions() {
    const Sidebar = document.getElementById('Sidebar');
    const menuBtn = document.getElementById('menu-btn');
    const sidebarsBtn = document.getElementById('sidebars-btn');
    const menuItemsDropdown = document.querySelectorAll('.menu-item-dropdown');
    const menuItemsStatic = document.querySelectorAll('.menu-item-static');

    // sidebarsBtn/menuBtn are static markup (never recreated), but
    // wireMenuInteractions() itself re-runs on every menu render (search
    // filter, language switch, department change...) — without this guard,
    // each re-run stacked one more click listener onto the same button. An
    // even number of stacked listeners toggles the class an even number of
    // times per click, which cancels itself out and made the button look
    // completely dead (confirmed live: aria-expanded never changed).
    if (sidebarsBtn && !sidebarsBtn.dataset.wired) {
        sidebarsBtn.dataset.wired = '1';
        sidebarsBtn.addEventListener('click', () => {
            const isHidden = document.body.classList.toggle('sidebars-hidden');
            sidebarsBtn.setAttribute('aria-expanded', String(isHidden));
        });
    }

    // Celular: el menú se cierra con la X de adentro, tocando afuera (el velo oscuro es body::before: un toque ahí llega con body como objetivo) o con Escape.
    // Antes el botón de la barra de arriba quedaba tapado por el propio panel y no había cómo cerrarlo desde adentro.
    const closeSidebarOnPhone = () => {
        if (!document.body.classList.contains('sidebars-hidden')) return;
        document.body.classList.remove('sidebars-hidden');
        sidebarsBtn?.setAttribute('aria-expanded', 'false');
    };
    const sidebarHeader = Sidebar && Sidebar.querySelector('.header');
    if (sidebarHeader && !document.getElementById('sidebar-close-btn')) {
        const closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.id = 'sidebar-close-btn';
        closeBtn.className = 'sidebar-close-btn';
        closeBtn.setAttribute('aria-label', t('sidebar.closeMenu'));
        closeBtn.innerHTML = '<i class="bx bx-x" aria-hidden="true"></i>';
        closeBtn.addEventListener('click', closeSidebarOnPhone);
        sidebarHeader.appendChild(closeBtn);
    }
    if (!document.body.dataset.sidebarCloseWired) {
        document.body.dataset.sidebarCloseWired = '1';
        document.addEventListener('click', (event) => { if (event.target === document.body) closeSidebarOnPhone(); });
        document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeSidebarOnPhone(); });
    }

    if (menuBtn && !menuBtn.dataset.wired) {
        menuBtn.dataset.wired = '1';
        menuBtn.addEventListener('click', () => {
            const isMinimized = Sidebar.classList.toggle('minimize');
            menuBtn.setAttribute('aria-expanded', String(!isMinimized));
            syncSidebarToggleLabel();
            hideSidebarTooltip();
            hideSidebarFlyout();
            applySubmenuAbbreviations();
            // The sidebar's own collapse/expand transition (.Sidebar's own
            // "transition: width 0.5s ease" in Inicio-en.css) changes how
            // much width every .data-table-wrapper actually has, same as a
            // window resize would -- resizeAllDataTables (below) re-stretches
            // each table to match instead of leaving it sized for the old
            // width. Waits for the transition to actually finish (not a
            // fixed timeout guessing at that 0.5s) so it reads the sidebar's
            // real final width, not a mid-animation one; the 600ms fallback
            // covers prefers-reduced-motion or any other case where the
            // transition never fires its end event at all.
            let settled = false;
            const onSettled = () => { if (settled) return; settled = true; resizeAllDataTables(); };
            Sidebar.addEventListener('transitionend', function handler(e) {
                if (e.propertyName !== 'width') return;
                Sidebar.removeEventListener('transitionend', handler);
                onSettled();
            });
            setTimeout(onSettled, 600);
        });
    }

    menuItemsDropdown.forEach((menuItem) => {
        menuItem.addEventListener('click', (event) => {
            // A dropdown can now nest inside another one (Reportes >
            // Personalizados, the first 2-level-deep case in this sidebar) —
            // without stopPropagation, clicking the inner one also bubbles
            // up and fires the outer one's own handler, immediately
            // re-collapsing it. :scope > .sub-menu (not .sub-menu) makes
            // sure each handler only ever touches ITS OWN direct submenu,
            // never a nested one belonging to a child dropdown.
            event.stopPropagation();
            // Con la barra cerrada, el clic en el icono (o en un menú de la lista que sale al pasar el mouse) abre la barra con esa sección desplegada; si
            // ya estaba abierta, solo se abre la barra.
            if (Sidebar.classList.contains('minimize') && menuBtn) {
                hideSidebarFlyout();
                menuBtn.click();
                if (menuItem.classList.contains('sub-menu-toggle')) return;
            }
            const subMenu = menuItem.querySelector(':scope > .sub-menu');
            const isActive = menuItem.classList.toggle('sub-menu-toggle');
            if (subMenu) {
                if (isActive) {
                    subMenu.style.height = `${subMenu.scrollHeight + 6}px`;
                    subMenu.style.padding = '0.2rem 0';
                } else {
                    subMenu.style.height = '0';
                    subMenu.style.padding = '0';
                }
            }
            menuItemsDropdown.forEach((item) => {
                // Never collapse an ANCESTOR of the item just toggled open
                // (that would hide the very item the user just opened) —
                // only true siblings/unrelated dropdowns close, same
                // accordion behavior as before this nesting existed.
                if (item === menuItem || item.contains(menuItem)) return;
                const otherSubmenu = item.querySelector(':scope > .sub-menu');
                if (otherSubmenu) {
                    item.classList.remove('sub-menu-toggle');
                    otherSubmenu.style.height = '0';
                    otherSubmenu.style.padding = '0';
                }
            });
            // An ancestor dropdown's own .sub-menu height was fixed in
            // pixels back when IT was toggled open, based on its
            // scrollHeight at that time — before this nested one existed or
            // had this much content. Expanding/collapsing a nested dropdown
            // changes the parent's true content height, so every currently-
            // open ancestor needs its height re-measured now, or the
            // parent's stale (too-short) fixed height clips the nested
            // content that just appeared (arrow rotates, nothing visible).
            // scrollHeight on an overflow:hidden box never reports SMALLER
            // than the box's own current height (only larger, if content
            // overflows it) -- reading it while the old pixel height is
            // still applied would just hand back that same old number (plus
            // this +6, forever), growing by 6px on every click regardless
            // of what actually changed. Snapping to 'auto' first forces a
            // real natural-size measurement before computing the new target.
            let ancestor = menuItem.parentElement?.closest('.menu-item-dropdown.sub-menu-toggle');
            while (ancestor) {
                const ancestorSubMenu = ancestor.querySelector(':scope > .sub-menu');
                if (ancestorSubMenu) {
                    ancestorSubMenu.style.height = 'auto';
                    ancestorSubMenu.style.height = `${ancestorSubMenu.scrollHeight + 6}px`;
                }
                ancestor = ancestor.parentElement?.closest('.menu-item-dropdown.sub-menu-toggle');
            }
            // Al abrir o cerrar un apartado la lista crece o se encoge y puede aparecer o desaparecer la barra de desplazamiento: el menú se estrecha o se
            // ensancha unos píxeles y lo que cabía ya no cabe (o al revés). Las abreviaturas se miden otra vez con el ancho de ese momento: una ahora y otra al
            // terminar la animación (0.3 s).
            applySubmenuAbbreviations();
            setTimeout(applySubmenuAbbreviations, 380);
        });
    });

    menuItemsStatic.forEach((menuItem) => {
        menuItem.addEventListener('mouseenter', () => {
            if (!Sidebar.classList.contains('minimize')) return;
            menuItemsDropdown.forEach((item) => {
                const otherSubmenu = item.querySelector(':scope > .sub-menu');
                if (otherSubmenu) {
                    item.classList.remove('sub-menu-toggle');
                    otherSubmenu.style.height = '0';
                    otherSubmenu.style.padding = '0';
                }
            });
        });
    });

    // Collapsed-sidebar tooltip: shows the item's label next to its icon on
    // hover. Positioned explicitly via JS (not pure CSS :hover) — see the
    // note in Inicio-en.css on why the old CSS-only version never worked.
    document.querySelectorAll('.menu-item').forEach((menuItem) => {
        menuItem.addEventListener('mouseenter', () => showSidebarTooltip(menuItem, Sidebar));
        menuItem.addEventListener('mouseleave', hideSidebarTooltip);
    });
    wireSidebarFlyouts(Sidebar);

    // Con la barra abierta ya no sale la etiqueta negra con el nombre completo al pasar el mouse por un nombre abreviado o cortado (Daniel, 2026-10-07):
    // el nombre completo se ve con la barra cerrada, en la ruta de arriba y en Modo ayuda. showSubmenuTooltip se conserva porque la usan las filas del
    // Árbol Maestro (PermissionTree.js).
}

function getSidebarTooltip() {
    let tooltip = document.getElementById('sidebar-tooltip');
    if (!tooltip) {
        tooltip = document.createElement('div');
        tooltip.id = 'sidebar-tooltip';
        tooltip.className = 'sidebar-tooltip';
        document.body.appendChild(tooltip);
    }
    return tooltip;
}

function showSidebarTooltip(menuItem, Sidebar) {
    // Confirmed live, 2026-09-30: hovering an abbreviated sidebar item while
    // Modo ayuda is active showed this plain "full name" tooltip stacked
    // right on top of Modo ayuda's own richer one after the click -- same
    // name shown twice, reading as "2 mensajes". This tooltip's whole job
    // (reveal the real name) is already covered by Modo ayuda's, so it steps
    // aside while that mode is on instead of fighting for the same space.
    if (helpModeActive) return;
    if (!Sidebar.classList.contains('minimize')) return;
    if (menuItem.matches('.menu-item-dropdown') && menuItem.querySelector(':scope > .sub-menu > li')) return;
    const label = menuItem.querySelector('.menu-link > span')?.textContent;
    if (!label) return;
    const tooltip = getSidebarTooltip();
    tooltip.textContent = label;
    const rect = menuItem.getBoundingClientRect();
    tooltip.style.top = `${rect.top + rect.height / 2}px`;
    tooltip.style.left = `${rect.right + 8}px`;
    tooltip.classList.add('visible');
}

// For a label CSS actually ellipsized (scrollWidth > clientWidth) --
// "Ingresos"/"Gastos" and every other short sub-menu label never triggers
// this, so nothing changes for them. A label with its own abbrLadder (see
// buildSubmenu/applySubmenuAbbreviations) always shows its tooltip instead,
// even once shortened enough to fit with no overflow -- the point of the
// tooltip there isn't "this got cut off", it's "here's the real full name".
// `link` is usually an <a> with its label in a child <span> (sidebar), but
// also accepts being handed the label <span> itself directly (Árbol
// Maestro's row labels, wired from PermissionTree.js) -- same tooltip,
// reused as-is rather than duplicated for that other caller.
function showSubmenuTooltip(link) {
    // Same reasoning as showSidebarTooltip's own guard just above.
    if (helpModeActive) return;
    const span = link.querySelector('span') || (link.tagName === 'SPAN' ? link : null);
    if (!span) return;
    const ladder = span.dataset.abbrLadder ? JSON.parse(span.dataset.abbrLadder) : null;
    const fullLabel = ladder ? ladder[0] : span.textContent;
    const isAbbreviated = ladder && span.textContent !== fullLabel;
    if (!isAbbreviated && span.scrollWidth <= span.clientWidth) return;
    const tooltip = getSidebarTooltip();
    tooltip.textContent = fullLabel;
    const rect = link.getBoundingClientRect();
    tooltip.style.top = `${rect.top + rect.height / 2}px`;
    tooltip.style.left = `${rect.right + 8}px`;
    tooltip.classList.add('visible');
}

function hideSidebarTooltip() {
    document.getElementById('sidebar-tooltip')?.classList.remove('visible');
}

// --- Barra cerrada: lista de opciones al pasar el mouse ----------------------------------------------------------------------------
// Con la barra cerrada, pasar el mouse por un icono con opciones dentro muestra a su lado SOLO la franja con el nombre de la sección; las opciones se
// despliegan hacia abajo cuando el mouse llega a esa franja (y otra lista por cada nivel de adentro) para elegir sin abrir la barra: una PANTALLA abre la
// pantalla; un MENÚ (algo que a su vez tiene opciones) abre la barra con ese menú desplegado; el clic en el icono también abre la barra con su sección.
// La lista se arma del propio menú ya dibujado (.sub-menu), así respeta permisos, búsqueda, idioma y abreviaturas.
let sidebarFlyoutRoot = null;
let sidebarFlyoutCloseTimer = null;
let sidebarFlyoutOwner = null;
const SIDEBAR_FLYOUT_CLOSE_DELAY_MS = 180;
const SIDEBAR_KEEP_COLLAPSED_KEY = 'sgn.sidebarKeepCollapsed';

function getSidebarFlyoutRoot() {
    if (sidebarFlyoutRoot && document.body.contains(sidebarFlyoutRoot)) return sidebarFlyoutRoot;
    const rootEl = document.createElement('div');
    rootEl.id = 'sidebar-flyout-root';
    rootEl.className = 'sidebar-flyout-root';
    rootEl.addEventListener('mouseenter', cancelSidebarFlyoutClose);
    rootEl.addEventListener('mouseleave', scheduleSidebarFlyoutClose);
    document.body.appendChild(rootEl);
    sidebarFlyoutRoot = rootEl;
    return rootEl;
}
function cancelSidebarFlyoutClose() {
    clearTimeout(sidebarFlyoutCloseTimer);
    sidebarFlyoutCloseTimer = null;
}
function scheduleSidebarFlyoutClose() {
    cancelSidebarFlyoutClose();
    sidebarFlyoutCloseTimer = setTimeout(hideSidebarFlyout, SIDEBAR_FLYOUT_CLOSE_DELAY_MS);
}
function hideSidebarFlyout() {
    cancelSidebarFlyoutClose();
    sidebarFlyoutOwner = null;
    if (sidebarFlyoutRoot) sidebarFlyoutRoot.replaceChildren();
}

// El nombre completo de una entrada (la abreviatura que ve la barra abierta no): igual que el tooltip.
function sidebarEntryLabel(link) {
    const span = link.querySelector('span');
    const ladder = span && span.dataset.abbrLadder ? JSON.parse(span.dataset.abbrLadder) : null;
    return ladder ? ladder[0] : (span ? span.textContent : (link.getAttribute('aria-label') || ''));
}

// Abre la barra con la cadena de menús desplegada hasta el elegido (el de más arriba primero), reutilizando el clic de cada uno.
function openSidebarMenuPath(sourceLi) {
    hideSidebarFlyout();
    const Sidebar = document.getElementById('Sidebar');
    if (Sidebar && Sidebar.classList.contains('minimize')) document.getElementById('menu-btn')?.click();
    const chain = [];
    for (let el = sourceLi; el; el = el.parentElement ? el.parentElement.closest('.menu-item-dropdown') : null) chain.unshift(el);
    chain.forEach((li) => {
        if (!li.classList.contains('sub-menu-toggle')) li.querySelector(':scope > a')?.click();
    });
}

// La franja de la sección queda alineada con su icono (la flecha apunta al centro del icono aunque la lista deba subirse para caber).
function syncSidebarFlyoutNotch(panel) {
    const anchorY = Number(panel.dataset.anchorY);
    if (!Number.isFinite(anchorY)) return;
    panel.style.setProperty('--flyout-notch-top', `${Math.round(anchorY - panel.getBoundingClientRect().top - 6)}px`);
}

function placeSidebarFlyoutPanel(panel, anchorRect, gap) {
    // Las listas de segundo nivel arrancan un poco arriba de su fila; la franja de la sección, justo a la altura de su icono (1 px por el borde).
    const isSection = panel.classList.contains('sidebar-flyout-section');
    const offset = isSection ? 1 : 8;
    if (!isSection) panel.style.maxHeight = `${window.innerHeight - 16}px`;
    panel.style.left = `${Math.round(anchorRect.right + gap)}px`;
    panel.style.top = `${Math.max(8, Math.round(anchorRect.top - offset))}px`;
    const height = panel.getBoundingClientRect().height;
    if (anchorRect.top - offset + height > window.innerHeight - 8) panel.style.top = `${Math.max(8, Math.round(window.innerHeight - height - 8))}px`;
    if (isSection) {
        panel.dataset.anchorY = String(anchorRect.top + (anchorRect.height || 0) / 2);
        syncSidebarFlyoutNotch(panel);
    }
}

// Despliega las opciones de la sección (solo pasa al llegar a su franja). Si ya no caben hacia abajo, la lista sube lo justo.
function openSidebarFlyoutSection(panel) {
    if (!panel || panel.classList.contains('open')) return;
    panel.classList.add('open');
    const head = panel.querySelector('.sidebar-flyout-head');
    const list = panel.querySelector('.sidebar-flyout-list');
    if (head) head.setAttribute('aria-expanded', 'true');
    if (!head || !list) return;
    const finalHeight = head.offsetHeight + Math.min(list.scrollHeight, parseFloat(list.style.maxHeight) || list.scrollHeight) + 2;
    const top = parseFloat(panel.style.top) || 0;
    if (top + finalHeight > window.innerHeight - 8) panel.style.top = `${Math.max(8, Math.round(window.innerHeight - finalHeight - 8))}px`;
    syncSidebarFlyoutNotch(panel);
}

// `section` (solo el primer nivel): { iconClass } -> la lista nace cerrada y arriba lleva la franja con el icono y el nombre de la sección.
function buildSidebarFlyoutPanel(title, subMenuEl, depth, anchorRect, gap, section) {
    const rootEl = getSidebarFlyoutRoot();
    // Al abrir una lista de este nivel se cierran las de los niveles de abajo.
    [...rootEl.querySelectorAll('.sidebar-flyout-panel')].filter((p) => Number(p.dataset.depth) >= depth).forEach((p) => p.remove());
    const panel = document.createElement('div');
    panel.className = section ? 'sidebar-flyout-panel sidebar-flyout-section' : 'sidebar-flyout-panel';
    panel.dataset.depth = String(depth);
    panel.setAttribute('role', 'menu');
    let head = null;
    if (section) {
        head = document.createElement('div');
        head.className = 'sidebar-flyout-head';
        head.tabIndex = 0;
        head.setAttribute('role', 'button');
        head.setAttribute('aria-expanded', 'false');
        head.setAttribute('aria-label', title);
        head.setAttribute('data-help-key', 'sidebarFlyoutSection');
        if (anchorRect.height) head.style.minHeight = `${Math.round(anchorRect.height)}px`;
        const chip = document.createElement('span');
        chip.className = 'sidebar-flyout-chip';
        if (section.iconClass) {
            const icon = document.createElement('i');
            icon.className = section.iconClass;
            icon.setAttribute('aria-hidden', 'true');
            chip.appendChild(icon);
        }
        const name = document.createElement('span');
        name.className = 'sidebar-flyout-name';
        name.textContent = title;
        const chevron = document.createElement('i');
        chevron.className = 'bx bx-chevron-down sidebar-flyout-chevron';
        chevron.setAttribute('aria-hidden', 'true');
        head.append(chip, name, chevron);
        panel.appendChild(head);
    } else if (title) {
        const heading = document.createElement('div');
        heading.className = 'sidebar-flyout-title';
        heading.textContent = title;
        panel.appendChild(heading);
    }
    const currentPage = window.location.pathname.split('/').pop();
    const ul = document.createElement('ul');
    ul.className = 'sidebar-flyout-list';
    [...subMenuEl.children].forEach((sourceLi) => {
        const sourceLink = sourceLi.querySelector(':scope > a');
        if (!sourceLink) return;
        const childMenu = sourceLi.querySelector(':scope > .sub-menu');
        const hasChildren = !!(childMenu && childMenu.children.length);
        const label = sidebarEntryLabel(sourceLink);
        const li = document.createElement('li');
        const a = document.createElement('a');
        a.className = 'sidebar-flyout-link';
        a.setAttribute('role', 'menuitem');
        a.setAttribute('aria-label', label);
        a.setAttribute('data-help-key', 'sidebarNavigation');
        const text = document.createElement('span');
        text.textContent = label;
        a.appendChild(text);
        const href = sourceLink.getAttribute('href') || '#';
        if (hasChildren) {
            // Un menú: al elegirlo se abre la barra con él desplegado.
            a.href = '#';
            a.classList.add('sidebar-flyout-menu');
            a.setAttribute('aria-haspopup', 'true');
            const chevron = document.createElement('i');
            chevron.className = 'bx bx-chevron-right';
            chevron.setAttribute('aria-hidden', 'true');
            a.appendChild(chevron);
            a.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                openSidebarMenuPath(sourceLi);
            });
        } else {
            // Una pantalla: navega a ella con la barra cerrada. Sin dirección todavía ('#'), no hace nada.
            a.href = href;
            if (href === '#') a.addEventListener('click', (event) => event.preventDefault());
            else {
                if (hrefMatchesPage(href.split('#')[0].split('/').pop(), currentPage)) li.classList.add('sidebar-flyout-current');
                // La pantalla nueva carga con la barra abierta por defecto; esta marca hace que arranque cerrada, como la dejó quien eligió desde la lista.
                a.addEventListener('click', (event) => {
                    if (event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || event.button !== 0) return;
                    try { sessionStorage.setItem(SIDEBAR_KEEP_COLLAPSED_KEY, '1'); } catch { /* sin almacenamiento: la pantalla abre con la barra abierta */ }
                });
            }
        }
        li.addEventListener('mouseenter', () => {
            cancelSidebarFlyoutClose();
            [...rootEl.querySelectorAll('.sidebar-flyout-panel')].filter((p) => Number(p.dataset.depth) > depth).forEach((p) => p.remove());
            if (hasChildren) {
                // Pegada al borde de ESTA lista (no al de la fila, que queda unos px adentro) y a la altura de la fila.
                buildSidebarFlyoutPanel(label, childMenu, depth + 1, { top: li.getBoundingClientRect().top, right: panel.getBoundingClientRect().right }, 2);
            }
        });
        li.appendChild(a);
        ul.appendChild(li);
    });
    if (section) {
        // La lista va dentro de una parte que se despliega (cerrada hasta que el mouse llega a la franja); si es muy larga se desplaza sola.
        ul.style.maxHeight = `${Math.max(120, window.innerHeight - 80)}px`;
        const drop = document.createElement('div');
        drop.className = 'sidebar-flyout-drop';
        const inner = document.createElement('div');
        inner.className = 'sidebar-flyout-drop-inner';
        inner.appendChild(ul);
        drop.appendChild(inner);
        panel.appendChild(drop);
        const expand = () => { cancelSidebarFlyoutClose(); openSidebarFlyoutSection(panel); };
        head.addEventListener('mouseenter', expand);
        head.addEventListener('focus', expand);
        head.addEventListener('click', expand);
        head.addEventListener('keydown', (event) => {
            if (event.key !== 'Enter' && event.key !== ' ' && event.key !== 'ArrowDown') return;
            event.preventDefault();
            expand();
            ul.querySelector('.sidebar-flyout-link')?.focus();
        });
    } else {
        panel.appendChild(ul);
    }
    rootEl.appendChild(panel);
    placeSidebarFlyoutPanel(panel, anchorRect, gap);
    return panel;
}

function wireSidebarFlyouts(Sidebar) {
    document.querySelectorAll('#Sidebar .menu-item-dropdown').forEach((menuItem) => {
        const subMenu = menuItem.querySelector(':scope > .sub-menu');
        if (!subMenu || !subMenu.children.length) return;
        const open = () => {
            if (!Sidebar.classList.contains('minimize') || helpModeActive) return;
            // La barra todavía se está cerrando (su ancho cambia durante medio segundo): se espera a que termine para colocar la franja junto a su borde final.
            const closing = Sidebar.getAnimations ? Sidebar.getAnimations().filter((animation) => animation.playState === 'running' || animation.playState === 'pending') : [];
            if (closing.length) {
                Promise.allSettled(closing.map((animation) => animation.finished)).then(() => { if (menuItem.matches(':hover')) open(); });
                return;
            }
            cancelSidebarFlyoutClose();
            hideSidebarTooltip();
            if (sidebarFlyoutOwner === menuItem) return;
            sidebarFlyoutOwner = menuItem;
            const link = menuItem.querySelector(':scope > .menu-link');
            // Solo sale la franja con el nombre, a la altura del icono y pegada al borde de la barra (no al del icono, que queda 16 px adentro); las opciones se
            // despliegan cuando el mouse llega a la franja.
            const linkRect = (link || menuItem).getBoundingClientRect();
            const sectionIcon = link ? link.querySelector(':scope > i') : null;
            buildSidebarFlyoutPanel(link ? sidebarEntryLabel(link) : '', subMenu, 1,
                { top: linkRect.top, height: linkRect.height, right: Sidebar.getBoundingClientRect().right }, 6,
                { iconClass: sectionIcon ? sectionIcon.className : '' });
        };
        menuItem.addEventListener('mouseenter', open);
        menuItem.addEventListener('focusin', open);
        menuItem.addEventListener('mouseleave', scheduleSidebarFlyoutClose);
        // Con teclado: la flecha derecha pasa de la sección a su franja.
        menuItem.addEventListener('keydown', (event) => {
            if (event.key !== 'ArrowRight' || sidebarFlyoutOwner !== menuItem) return;
            const head = sidebarFlyoutRoot && sidebarFlyoutRoot.querySelector('.sidebar-flyout-head');
            if (!head) return;
            event.preventDefault();
            head.focus();
        });
    });
    // Los demás iconos (Inicio, Tablero... sin nada dentro) cierran la lista abierta: solo muestran su nombre.
    document.querySelectorAll('#Sidebar .menu-item-static, #Sidebar .search').forEach((el) => el.addEventListener('mouseenter', hideSidebarFlyout));
    if (!document.body.dataset.sidebarFlyoutWired) {
        document.body.dataset.sidebarFlyoutWired = '1';
        // Venimos de elegir una pantalla desde la lista de la barra cerrada: la barra sigue cerrada (se usa una sola vez).
        let keepCollapsed = false;
        try { keepCollapsed = sessionStorage.getItem(SIDEBAR_KEEP_COLLAPSED_KEY) === '1'; sessionStorage.removeItem(SIDEBAR_KEEP_COLLAPSED_KEY); } catch { /* sin almacenamiento */ }
        if (keepCollapsed && window.matchMedia('(min-width: 781px) and (min-height: 551px)').matches) {
            Sidebar.classList.add('minimize');
            document.getElementById('menu-btn')?.setAttribute('aria-expanded', 'false');
            syncSidebarToggleLabel();
        }
        window.addEventListener('resize', hideSidebarFlyout);
        document.addEventListener('keydown', (event) => { if (event.key === 'Escape') hideSidebarFlyout(); });
        // Al desplazar la página la lista se cierra; desplazar la propia lista (si es larga) no.
        document.addEventListener('scroll', (event) => {
            if (sidebarFlyoutRoot && event.target instanceof Node && sidebarFlyoutRoot.contains(event.target)) return;
            hideSidebarFlyout();
        }, true);
    }
}

// Un "resize" con el mismo tamaño de ventana (el visor lo dispara al cargar la pantalla) no es un cambio real: no debe volver a abrir una barra que quedó cerrada a propósito.
let lastViewportSize = `${window.innerWidth}x${window.innerHeight}`;
function checkWindowSize() {
    const size = `${window.innerWidth}x${window.innerHeight}`;
    if (size === lastViewportSize) return;
    lastViewportSize = size;
    document.getElementById('Sidebar')?.classList.remove('minimize');
}
window.addEventListener('resize', checkWindowSize);

// --- Top-bar overflow: collapse based on real measured collision, not a
// fixed viewport width. A fixed breakpoint never held here — how many
// action icons Dashboard.js inserts varies by account (6 to 9), pill
// labels vary by department/language, and browser zoom changes the
// effective content width without changing window.innerWidth. Two-stage
// cascade, both against ACTUAL layout: first collapse the action icons
// behind "⋮" once .top-bar-title would touch them; if the title still
// collides with that now-much-narrower "⋮" button, hide the title too.
// See .top-bar-icons-collapsed / .top-bar-title-hidden in Inicio-en.css.
function checkTopBarFit() {
    const topBar = document.querySelector('.top-bar');
    const titleGroup = document.querySelector('.top-bar-title');
    const actionsGroup = document.getElementById('top-bar-actions');
    if (!topBar || !titleGroup || !actionsGroup) return;

    // Reset to the fullest state before measuring — an already-collapsed
    // state hides content, which would give a false "plenty of room" read.
    topBar.classList.remove('top-bar-icons-collapsed', 'top-bar-title-hidden');

    const GAP = 12; // px of breathing room before calling it a collision
    // El nombre de la pantalla (regla de todo el sistema, Daniel 2026-11-19: si no cabe, se abrevia): primero se prueba todo completo; si choca, los iconos se recogen detrás de «⋮» (como siempre) y, si el
    // título todavía choca, en lugar de esconderlo se abrevia (la escalera de la barra lateral) hasta que quepa. Solo si ni abreviado cabe se esconde. Se mide con el propio diseño, siempre partiendo del
    // nombre completo, así da la misma respuesta cada vez; el observador del título se suelta mientras se escribe para que este ajuste no se llame a sí mismo.
    const title = titleGroup.querySelector('.welcome-text');
    const info = topBarTitleInfo(title);
    const collides = () => titleGroup.getBoundingClientRect().right + GAP > actionsGroup.getBoundingClientRect().left;
    if (topBarTitleObserver) topBarTitleObserver.disconnect();
    try {
        setTopBarTitleText(title, info, 0);
        if (!collides()) return;
        topBar.classList.add('top-bar-icons-collapsed');
        // Re-measure: the icons are now tucked behind "⋮", a much narrower
        // target — only hide the title too if it's STILL colliding against that.
        if (!collides()) return;
        for (let step = 1; info && step < info.ladder.length; step += 1) {
            setTopBarTitleText(title, info, step);
            if (!collides()) return;
        }
        setTopBarTitleText(title, info, 0);
        topBar.classList.add('top-bar-title-hidden');
    } finally {
        if (topBarTitleObserver && topBarTitleEl) topBarTitleObserver.observe(topBarTitleEl, { childList: true, subtree: true, characterData: true });
    }
}
// El nombre completo del título y su escalera de abreviaturas. El texto que otra parte del código escribe en el título (cambiar de pantalla, de idioma) se toma como el completo nuevo; el que dejó este
// ajuste se reconoce (abbrShown) para no confundirlo con el completo. Un título con enlaces o iconos adentro no es solo texto: no se toca.
function topBarTitleInfo(title) {
    if (!title || title.children.length || !title.textContent.trim()) return null;
    const current = title.textContent;
    const full = title.dataset.abbrShown !== undefined && current === title.dataset.abbrShown ? title.dataset.abbrFull : current;
    return { full, ladder: autoAbbrLadder(full) };
}
function setTopBarTitleText(title, info, step) {
    if (!title || !info) return;
    const text = info.ladder[step] !== undefined ? info.ladder[step] : info.full;
    if (title.textContent !== text) title.textContent = text;
    if (step > 0) {
        title.dataset.abbrFull = info.full;
        title.dataset.abbrShown = text;
        if (!title.hasAttribute('title') || title.dataset.abbrTitle) { title.title = info.full; title.dataset.abbrTitle = '1'; }
    } else {
        delete title.dataset.abbrFull;
        delete title.dataset.abbrShown;
        if (title.dataset.abbrTitle) { title.removeAttribute('title'); delete title.dataset.abbrTitle; }
    }
}
let topBarFitTimer = null;
function scheduleTopBarFitCheck() {
    // A plain requestAnimationFrame debounce (~16ms) fired mid-animation
    // whenever the sidebar slides in/out (.Sidebar has its own 0.3s CSS
    // transition) — each firing re-measured while the layout was still
    // moving, and since the real geometry genuinely differs frame to
    // frame during that animation, the collapsed/uncollapsed outcome
    // legitimately flip-flopped call to call, visible as the action icons
    // rapidly opening/closing in sync with the sidebar's own motion.
    // Waiting past the transition's own duration before measuring means
    // every check happens against the settled, final layout instead.
    if (topBarFitTimer) clearTimeout(topBarFitTimer);
    topBarFitTimer = setTimeout(checkTopBarFit, 350);
}
window.addEventListener('resize', scheduleTopBarFitCheck);
scheduleTopBarFitCheck();
// Catches department/area/cost-center picker labels loading in, language
// switches, and any other content change inside the title group — without
// needing to separately hook every call site that might affect its width.
const topBarTitleEl = document.querySelector('.top-bar-title');
let topBarTitleObserver = null;
if (topBarTitleEl) {
    topBarTitleObserver = new MutationObserver(scheduleTopBarFitCheck);
    topBarTitleObserver.observe(topBarTitleEl, { childList: true, subtree: true, characterData: true });
}

// Every dropdown/panel below (top-bar-actions overflow, Configuración,
// Datos de Usuario, Datos de Usuario del Negocio, chatbot, Departamento/
// Área/Centro de Costos pickers, sidebar search results) has its own toggle
// button that calls event.stopPropagation() so opening it doesn't
// immediately trigger ITS OWN "click outside closes it" listener below —
// but that stopPropagation also stops the click from ever reaching
// document, so every OTHER menu's "click outside" listener never runs
// either. That's why clicking one top-bar button while another's dropdown
// is open used to leave both open at once. Each toggle now closes every
// registered dropdown first (see closeAllTopBarDropdowns) before deciding
// whether to open itself.
const topBarDropdownClosers = [];
function registerTopBarDropdown(closeFn, name) {
    topBarDropdownClosers.push({ closeFn, name });
}
// exceptName skips one registered closer — needed by every dropdown that
// physically LIVES INSIDE .top-bar-actions-list (Configuración, Datos de
// Usuario, Datos del Negocio, Chatbot, Tamaño del Sistema, Notificaciones):
// calling this with no exclusion from one of THEM also closed
// top-bar-actions itself (its own container), which set that dropdown's
// .open class as intended but left it sitting inside a now-invisible
// (opacity:0, visibility:hidden) ancestor — LOOKED exactly like "opens
// then immediately closes" with no error and no timing issue to guard
// against, because nothing was ever actually racing.
function closeAllTopBarDropdowns(exceptName) {
    // Bare calls (no exceptName) come from every OTHER picker's own click
    // handler (dept/area/cc, settings, user info, business profile,
    // notifications...) and none of them pass their own name — so
    // `name !== exceptName` was comparing undefined !== undefined for
    // every one of them and skipping ALL of them, closing only the one
    // dropdown that happens to be registered with a real name
    // ('topBarActions'). `!name` makes every unnamed closer close
    // unconditionally; a named one still only stays open when it's the
    // caller's own exceptName.
    topBarDropdownClosers.forEach(({ closeFn, name }) => { if (!name || name !== exceptName) closeFn(); });
}

// Clicking the sidebar logo/brand reloads the page instead of doing
// nothing — a plain full reload (not a client-side "refetch everything"
// call) so it always picks up a newer deploy too, not just fresher data.
// .brand is static markup shared by every page that loads this file
// (every Business-*.html client screen and Admin-SaaS.html alike), so this
// one binding covers the SaaS panel and every client, present and future,
// with nothing per-page to wire up.
document.querySelectorAll('.brand').forEach((brand) => {
    brand.style.cursor = 'pointer';
    brand.addEventListener('click', () => {
        sessionStorage.setItem('sgnShowUpdateToast', '1');
        window.location.reload();
    });
});

// --- Top-bar actions collapse (mobile only) ----------------------------------
// On phones, Messages/Chatbot/Notifications/Bookmarks/Settings/Add-user don't
// all fit next to the page title, so they collapse behind a single toggle
// button and open as a dropdown — CSS handles hiding .top-bar-actions-list
// vs. showing it inline, this just tracks the open/close state.
const topBarActions = document.getElementById('top-bar-actions');
const topBarActionsToggle = document.getElementById('top-bar-actions-toggle');

function closeTopBarActions() {
    topBarActions?.classList.remove('open');
    topBarActionsToggle?.setAttribute('aria-expanded', 'false');
}
registerTopBarDropdown(closeTopBarActions, 'topBarActions');

// openedAt guards against the exact tap that OPENS the menu also being the
// one that closes it: some mobile browsers dispatch a synthetic click for a
// touch tap that lands on `document` as a second, separate event rather
// than bubbling through the normal chain — stopPropagation() below has no
// effect on that second dispatch since it never passed through this
// listener at all. Reported on mobile as "tap the ⋮ button, it opens then
// immediately closes". Ignoring any outside-click within 300ms of opening
// is long enough to absorb that stray duplicate, short enough that a real
// deliberate tap-elsewhere-to-close still works instantly.
let topBarActionsOpenedAt = 0;
topBarActionsToggle?.addEventListener('click', (event) => {
    event.stopPropagation();
    const wasOpen = topBarActions.classList.contains('open');
    closeAllTopBarDropdowns();
    if (!wasOpen) {
        topBarActions.classList.add('open');
        topBarActionsToggle.setAttribute('aria-expanded', 'true');
        topBarActionsOpenedAt = Date.now();
    }
});

document.addEventListener('click', (event) => {
    if (Date.now() - topBarActionsOpenedAt < 300) return;
    if (topBarActions && !topBarActions.contains(event.target)) closeTopBarActions();
});

document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeTopBarActions();
});

// --- Settings dropdown (Language / Style / Others) --------------------------
const settingsMenu = document.getElementById('settings-menu');
const settingsBtn = document.getElementById('settings-btn');
const settingsDropdown = document.getElementById('settings-dropdown');

function closeSettingsMenu() {
    settingsMenu?.classList.remove('open');
    settingsBtn?.setAttribute('aria-expanded', 'false');
    document.querySelectorAll('.settings-dropdown-group.open').forEach((group) => {
        group.classList.remove('open');
        group.querySelector('.settings-dropdown-toggle')?.setAttribute('aria-expanded', 'false');
        const submenu = group.querySelector('.settings-submenu');
        if (submenu) submenu.style.height = '0';
    });
}
registerTopBarDropdown(closeSettingsMenu);

// Same synthetic-duplicate-click guard as topBarActionsToggle above — this
// button lives inside .top-bar-actions-list, which below 1120px is itself
// behind the "more" toggle, so a touch tap here is just as likely to fire
// that extra document-level click. Without this guard the settings dropdown
// (Idioma/Estilo/...) opened and immediately closed on any screen narrower
// than 1120px.
let settingsMenuOpenedAt = 0;
settingsBtn?.addEventListener('click', (event) => {
    event.stopPropagation();
    const wasOpen = settingsMenu.classList.contains('open');
    closeAllTopBarDropdowns('topBarActions');
    if (!wasOpen) {
        settingsMenu.classList.add('open');
        settingsBtn.setAttribute('aria-expanded', 'true');
        settingsMenuOpenedAt = Date.now();
    }
});

document.addEventListener('click', (event) => {
    if (Date.now() - settingsMenuOpenedAt < 300) return;
    if (settingsMenu && !settingsMenu.contains(event.target)) closeSettingsMenu();
});

document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeSettingsMenu();
});

settingsDropdown?.addEventListener('click', (event) => {
    if (event.target.closest('button')) closeSettingsMenu();
});

// --- "Datos de Usuario" / "Datos Personales" panel ---------------------------
// Read-only, fetched once per page load and cached — re-opening the dropdown
// just re-shows the cached copy instead of refetching every time.
const userInfoMenu = document.getElementById('user-info-menu');
const userInfoBtn = document.getElementById('user-info-btn');
let cachedUserProfile = null;

function closeUserInfoMenu() {
    userInfoMenu?.classList.remove('open');
    userInfoBtn?.setAttribute('aria-expanded', 'false');
}
registerTopBarDropdown(closeUserInfoMenu);

// Re-run on language change too (see loadLanguage) so an already-fetched
// profile's fallback text ("Sin correo institucional" / "No registrado")
// re-translates instead of staying stuck in the old language.
function renderUserProfile() {
    if (!cachedUserProfile) return;
    const setField = (id, value, fallbackKey) => {
        const el = document.getElementById(id);
        if (el) el.textContent = value || t(fallbackKey);
    };
    setField('user-info-nickname', cachedUserProfile.nickname, 'main.notSet');
    setField('user-info-business-email', cachedUserProfile.business_email, 'main.noBusinessEmail');
    setField('user-info-name', cachedUserProfile.name, 'main.notSet');
    setField('user-info-phone', cachedUserProfile.phone, 'main.notSet');
    setField('user-info-address', cachedUserProfile.address, 'main.notSet');
    setField('user-info-birth-date', cachedUserProfile.birth_date, 'main.notSet');
    setField('user-info-id-number', cachedUserProfile.id_number, 'main.notSet');
    renderUserPhotoBlock();
}

async function loadUserProfile() {
    if (cachedUserProfile) {
        renderUserProfile();
        return;
    }
    try {
        const res = await fetch('/api/me/profile');
        if (!res.ok) return;
        const { profile } = await res.json();
        cachedUserProfile = profile;
        renderUserProfile();
    } catch (err) {
        console.error('Failed to load user profile:', err);
    }
}

// --- Foto de usuario (pieza 4 de Equipo de Trabajo) ---------------------------------------------------------------------------
// La sube la propia persona desde «Datos de usuario»: el navegador la recorta al centro y la achica a 256 px (JPEG) antes de mandarla; el servidor la guarda (user_photos) y cada versión trae su número (?v=).
// Sale en el tablero de Equipo de Trabajo y en la tarjeta de la barra lateral. Solo cuentas de una compañía (la cuenta del equipo SaaS no tiene foto).
const USER_PHOTO_SIZE = 256;
const userPhotoUrl = (userId, ver) => `/api/business/users/${userId}/photo?v=${ver}`;
// La imagen se abre sin direcciones blob: (la política de seguridad solo deja 'self' y data:): createImageBitmap y, si el navegador no lo tiene, el archivo leído como data:.
async function loadUserPhotoSource(file) {
    if (window.createImageBitmap) {
        try { return await createImageBitmap(file); } catch (err) { /* sigue con el respaldo */ }
    }
    const dataUrl = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); });
    return new Promise((resolve, reject) => { const img = new Image(); img.onload = () => resolve(img); img.onerror = () => reject(new Error('image')); img.src = dataUrl; });
}
async function resizeUserPhoto(file) {
    const source = await loadUserPhotoSource(file);
    const width = source.naturalWidth || source.width;
    const height = source.naturalHeight || source.height;
    const side = Math.min(width, height);
    if (!side) throw new Error('image');
    const canvas = document.createElement('canvas');
    canvas.width = USER_PHOTO_SIZE;
    canvas.height = USER_PHOTO_SIZE;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, USER_PHOTO_SIZE, USER_PHOTO_SIZE);
    ctx.drawImage(source, (width - side) / 2, (height - side) / 2, side, side, 0, 0, USER_PHOTO_SIZE, USER_PHOTO_SIZE);
    if (source.close) source.close();
    return new Promise((resolve, reject) => canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('blob'))), 'image/jpeg', 0.85));
}
function setUserPhotoError(text) {
    const el = document.getElementById('user-photo-error');
    if (el) { el.textContent = text || ''; el.hidden = !text; }
}
async function sendUserPhoto(method, body) {
    const res = await fetch('/api/me/photo', { method, credentials: 'include', headers: body ? { 'Content-Type': 'image/jpeg' } : {}, body });
    const out = await res.json().catch(() => ({}));
    if (!res.ok) { const err = new Error(out.message || 'failed'); err.code = out.code; throw err; }
    return out;
}
function userPhotoChanged(ver, messageKey) {
    cachedUserProfile.photoVer = ver;
    renderUserPhotoBlock();
    renderSidebarUserCard();
    document.dispatchEvent(new CustomEvent('user-photo-changed', { detail: { ver } }));
    showToast(t(messageKey), 'success');
}
async function onUserPhotoPick(event) {
    const input = event.target.closest('#user-photo-file');
    if (!input || !input.files || !input.files[0]) return;
    const file = input.files[0];
    input.value = '';
    setUserPhotoError('');
    if (!/^image\/(png|jpeg|webp)$/i.test(file.type)) { setUserPhotoError(t('main.userPhotoErr_FILE')); return; }
    try {
        const blob = await resizeUserPhoto(file);
        const out = await sendUserPhoto('PUT', blob);
        userPhotoChanged(out.photoVer, 'main.userPhotoSaved');
    } catch (err) {
        const key = err && err.code ? `main.userPhotoErr_${err.code}` : '';
        setUserPhotoError(key && t(key) !== key ? t(key) : t('main.userPhotoErr'));
    }
}
async function onUserPhotoClick(event) {
    const btn = event.target.closest('[data-photo]');
    if (!btn) return;
    if (btn.dataset.photo === 'pick') { const input = document.getElementById('user-photo-file'); if (input) input.click(); return; }
    setUserPhotoError('');
    try { const out = await sendUserPhoto('DELETE'); userPhotoChanged(out.photoVer, 'main.userPhotoRemoved'); } catch (err) { setUserPhotoError(t('main.userPhotoErr')); }
}
function renderUserPhotoBlock() {
    const dropdown = document.getElementById('user-info-dropdown');
    if (!dropdown || !cachedUserProfile || !currentUser || !currentUser.clientId) return;
    let block = document.getElementById('user-photo-block');
    if (!block) {
        block = document.createElement('div');
        block.id = 'user-photo-block';
        block.className = 'user-info-group user-photo-block';
        block.setAttribute('data-help-key', 'userPhoto');
        dropdown.insertBefore(block, dropdown.firstChild);
        block.addEventListener('click', onUserPhotoClick);
        block.addEventListener('change', onUserPhotoPick);
    }
    const ver = cachedUserProfile.photoVer || 0;
    const name = cachedUserProfile.name || currentUser.name || currentUser.username || '';
    const title = document.createElement('h4');
    title.textContent = t('main.userPhoto');
    const avatar = document.createElement('span');
    avatar.className = 'user-photo-avatar';
    avatar.setAttribute('aria-hidden', 'true');
    if (ver) {
        const img = document.createElement('img');
        img.alt = '';
        img.src = userPhotoUrl(cachedUserProfile.id, ver);
        avatar.appendChild(img);
    } else avatar.textContent = userCardInitials(name);
    const actions = document.createElement('div');
    actions.className = 'user-photo-actions';
    const pick = document.createElement('button');
    pick.type = 'button';
    pick.className = 'btn btn-secondary user-photo-btn';
    pick.dataset.photo = 'pick';
    pick.textContent = t(ver ? 'main.userPhotoChange' : 'main.userPhotoUpload');
    actions.appendChild(pick);
    if (ver) {
        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'btn btn-secondary user-photo-btn';
        remove.dataset.photo = 'remove';
        remove.textContent = t('main.userPhotoRemove');
        actions.appendChild(remove);
    }
    const input = document.createElement('input');
    input.type = 'file';
    input.id = 'user-photo-file';
    input.accept = 'image/png,image/jpeg,image/webp';
    input.hidden = true;
    const error = document.createElement('p');
    error.id = 'user-photo-error';
    error.className = 'user-photo-error';
    error.setAttribute('role', 'alert');
    error.hidden = true;
    const row = document.createElement('div');
    row.className = 'user-photo-row';
    row.append(avatar, actions, input);
    block.replaceChildren(title, row, error);
}

